    @staticmethod
    def _sentence_has_clinical_decision_claim(sentence: str) -> bool:
        raw = str(sentence or "").lower()
        implementation_terms = (
            "clinical decision", "clinical decisions", "patient preferences",
            "patient preference", "eligible patients", "guideline panels",
            "shared decision", "implementation", "cost", "affordability",
            "monitoring", "处方决策", "临床决策", "患者偏好", "费用",
            "可及性", "实施", "监测", "适用患者",
        )
        clinical_content_terms = (
            "baseline risk", "absolute benefit", "safety", "renal function",
            "volume status", "adverse", "genitourinary", "ketoacidosis",
            "基线风险", "绝对获益", "安全", "肾功能", "容量状态", "不良",
            "泌尿", "酮症酸中毒",
        )
        return bool(
            any(term in raw for term in implementation_terms)
            and any(term in raw for term in clinical_content_terms)
        )

    @staticmethod
    def _sentence_has_primary_trial_count_claim(sentence: str) -> bool:
        raw = str(sentence or "").lower()
        if not re.search(r"\d", raw):
            return False
        english_participant_count = (
            re.search(r"\b(?:included|contributing|contributed|enrolled|randomized|randomised|total)\b", raw)
            and re.search(r"\b(?:participants|sample size|trial participants)\b", raw)
        )
        english_patient_count = (
            re.search(r"\b(?:contributing|contributed|enrolled|randomized|randomised|total)\b", raw)
            and re.search(r"\bpatients\b", raw)
        )
        chinese_count = re.search(
            r"(?:纳入|贡献|提供|总计|共).{0,16}(?:参与者|受试者|患者|样本量)",
            raw,
        )
        return bool(english_participant_count or english_patient_count or chinese_count)

    @staticmethod
    def _ensure_claim_specific_citation_supplements(
        manuscript: str,
        entries: list[dict[str, object]],
    ) -> str:
        """Add a narrow source when an interpretive paragraph only has generic citations."""
        if not entries:
            return manuscript

        updated = str(manuscript or "")
        for heading in (
            "Introduction", "Methods", "Results", "Discussion", "Conclusion",
            "引言", "方法", "结果", "讨论", "结论",
        ):
            pattern = rf"(^##\s+{re.escape(heading)}\s*$)([\s\S]*?)(?=^##\s+|\Z)"
            match = re.search(pattern, updated, flags=re.M)
            if not match:
                continue

            body = match.group(2)
            parts = re.split(r"(\n\s*\n)", body)
            changed = False
            for index in range(0, len(parts), 2):
                paragraph = parts[index]
                if not WritingAgent._paragraph_has_citable_line(paragraph):
                    continue
                if WritingAgent._paragraph_should_avoid_inline_citation_backfill(paragraph, heading=heading):
                    continue
                existing_numbers = set(WritingAgent._citation_numbers_from_text(paragraph))
                paragraph_without_citations = re.sub(
                    r"[\[［][0-9\s,，、;；\-–—至]+[\]］]",
                    " ",
                    paragraph,
                )
                minimum_units = min(12, PUBLICATION_CITATION_MIN_SUBSTANTIAL_PARAGRAPH_WORDS)
                if (
                    WritingAgent._text_unit_count(paragraph_without_citations)
                    < minimum_units
                ):
                    continue

                sentence_updated = WritingAgent._append_claim_specific_citations_to_sentences(
                    paragraph,
                    entries,
                    heading,
                )
                if sentence_updated != paragraph:
                    parts[index] = sentence_updated
                    changed = True
                    continue

                existing_numbers = set(WritingAgent._citation_numbers_from_text(paragraph))
                preferred = WritingAgent._claim_specific_reference_numbers(paragraph, entries, heading)
                if not preferred or existing_numbers & set(preferred):
                    continue
                missing = [number for number in preferred if number not in existing_numbers]
                citation = WritingAgent._citation_cluster(missing[:1])
                if not citation:
                    continue
                updated_paragraph = WritingAgent._append_citation_to_first_paragraph(paragraph, citation, heading=heading)
                if updated_paragraph != paragraph:
                    parts[index] = updated_paragraph
                    changed = True

            if changed:
                updated_body = "".join(parts)
                updated = updated[:match.start(2)] + updated_body + updated[match.end(2):]

        return updated

    @staticmethod
    def _append_claim_specific_citations_to_sentences(
        paragraph: str,
        entries: list[dict[str, object]],
        heading: str,
    ) -> str:
        """Cite the sentence that makes a claim instead of borrowing nearby citations."""
        lines = str(paragraph or "").splitlines()
        changed = False
        for line_index, line in enumerate(lines):
            if not WritingAgent._line_can_receive_citation(line):
                continue
            segments = WritingAgent._sentence_segments(line)
            if not segments:
                continue
            updated_segments: list[str] = []
            line_changed = False
            for segment in segments:
                segment_without_citations = re.sub(
                    r"[\[［][0-9\s,，、;；\-–—至]+[\]］]",
                    " ",
                    segment,
                )
                if WritingAgent._text_unit_count(segment_without_citations) < 12:
                    updated_segments.append(segment)
                    continue
                preferred = WritingAgent._claim_specific_reference_numbers(segment, entries, heading)
                if not preferred:
                    updated_segments.append(segment)
                    continue
                existing_numbers = set(WritingAgent._citation_numbers_from_text(segment))
                preferred_set = set(preferred)
                citation_limit = WritingAgent._claim_specific_sentence_citation_limit(segment)
                preserve_existing_complementary_numbers = (
                    WritingAgent._sentence_has_numeric_effect_claim(segment)
                    and not WritingAgent._sentence_has_primary_trial_count_claim(segment)
                )
                if existing_numbers & preferred_set:
                    trimmed_segment = (
                        segment
                        if preserve_existing_complementary_numbers
                        else WritingAgent._trim_narrow_claim_sentence_citations(segment, preferred)
                    )
                    existing_after_trim = set(WritingAgent._citation_numbers_from_text(trimmed_segment))
                    existing_preferred = existing_after_trim & preferred_set
                    if len(existing_preferred) < citation_limit:
                        missing_preferred = [
                            number for number in preferred
                            if number not in existing_after_trim
                        ]
                        if missing_preferred:
                            trimmed_segment = WritingAgent._append_citation_to_sentence(
                                trimmed_segment,
                                WritingAgent._citation_cluster(
                                    missing_preferred[:citation_limit - len(existing_preferred)]
                                ),
                            )
                            trimmed_segment = WritingAgent._merge_adjacent_citation_clusters(trimmed_segment)
                    updated_segments.append(trimmed_segment)
                    if trimmed_segment != segment:
                        line_changed = True
                    continue
                if len(existing_numbers) >= 5:
                    updated_segments.append(segment)
                    continue
                if existing_numbers:
                    replacement_segment = (
                        segment
                        if preserve_existing_complementary_numbers
                        else WritingAgent._trim_narrow_claim_sentence_citations(segment, preferred)
                    )
                    if replacement_segment != segment:
                        updated_segments.append(replacement_segment)
                        line_changed = True
                        continue
                missing = [number for number in preferred if number not in existing_numbers]
                citation = WritingAgent._citation_cluster(missing[:citation_limit])
                if not citation:
                    updated_segments.append(segment)
                    continue
                updated_segments.append(WritingAgent._append_citation_to_sentence(segment, citation))
                line_changed = True
            if line_changed:
                lines[line_index] = "".join(updated_segments)
                changed = True
        return "\n".join(lines) if changed else paragraph

    @staticmethod
    def _claim_specific_sentence_citation_limit(segment: str) -> int:
        raw = str(segment or "").lower()
        trial_terms = ("trial results", "trial evidence", "randomized evidence", "randomised evidence", "试验", "随机试验")
        mechanism_terms = ("biological plausibility", "mechanism", "mechanistic", "pathophysiology", "机制", "生物学合理", "病理生理")
        guideline_terms = ("guideline context", "guideline", "guidelines", "recommendation", "指南背景", "指南", "推荐")
        if (
            any(term in raw for term in trial_terms)
            and any(term in raw for term in mechanism_terms)
            and any(term in raw for term in guideline_terms)
        ):
            return 5
        if WritingAgent._sentence_has_clinical_decision_claim(raw):
            return 4
        if WritingAgent._sentence_has_primary_trial_count_claim(raw):
            return 2
        multi_source_terms = (
            "pooled hr", "pooled hazard ratio", "pooled effect",
            "absolute risk difference", "number needed to treat", "nnt",
            "合并hr", "合并效应", "绝对风险差", "需治数", "获益需治数",
        )
        return 2 if any(term in raw for term in multi_source_terms) else 1

    @staticmethod
    def _trim_narrow_claim_sentence_citations(segment: str, preferred_numbers: list[int]) -> str:
        """Keep safety/mechanism claim sentences from accumulating broad, unrelated bundles."""
        raw = str(segment or "")
        lowered = raw.lower()
        narrow_markers = (
            "safety", "adverse", "genitourinary", "ketoacidosis", "volume depletion",
            "renal-function", "renal function", "mechanism", "mechanistic", "osmotic",
            "diuresis", "natriuresis", "renal hemodynamics", "cardiometabolic",
            "pooled hr", "pooled hazard ratio", "pooled effect",
            "absolute risk difference", "number needed to treat", "nnt",
            "participants", "patients", "sample size", "clinical decision",
            "clinical decisions", "patient preferences", "cost",
            "安全", "不良", "泌尿", "酮症酸中毒", "容量不足", "肾功能",
            "机制", "利尿", "排钠", "血流动力学", "心肾代谢",
            "合并hr", "合并效应", "绝对风险差", "需治数", "获益需治数",
            "参与者", "受试者", "样本量", "临床决策", "患者偏好",
            "费用",
        )
        if not any(marker in lowered for marker in narrow_markers):
            return segment
        preferred = set(preferred_numbers)
        citation_pattern = r"[\[［][0-9\s,，、;；\-–—至]+[\]］]"
        existing = set(WritingAgent._citation_numbers_from_text(raw))
        kept = sorted(existing & preferred)
        if not kept:
            if not existing:
                return segment
            kept = preferred_numbers[:WritingAgent._claim_specific_sentence_citation_limit(raw)]
        if kept == sorted(existing):
            return segment
        without_citations = re.sub(citation_pattern, "", raw)
        without_citations = re.sub(r"\s+([.,;:!?。！？])", r"\1", without_citations)
        without_citations = re.sub(r"\s{2,}", " ", without_citations)
        return WritingAgent._append_citation_to_sentence(
            without_citations,
            WritingAgent._citation_cluster(kept),
        )

    @staticmethod
    def _smooth_mechanical_citation_density(manuscript: str) -> str:
        """Reduce visibly mechanical citation placement in interpretive paragraphs."""
        updated = str(manuscript or "")
        for heading in ("Methods", "Results", "Discussion", "Conclusion", "方法", "结果", "讨论", "结论"):
            pattern = rf"(^##\s+{re.escape(heading)}\s*$)([\s\S]*?)(?=^##\s+|\Z)"
            match = re.search(pattern, updated, flags=re.M)
            if not match:
                continue
            body = match.group(2)
            parts = re.split(r"(\n\s*\n)", body)
            changed = False
            for index in range(0, len(parts), 2):
                paragraph = parts[index]
                smoothed = WritingAgent._smooth_mechanical_citation_density_paragraph(paragraph)
                if smoothed != paragraph:
                    parts[index] = smoothed
                    changed = True
            if changed:
                updated_body = "".join(parts)
                updated = updated[:match.start(2)] + updated_body + updated[match.end(2):]
        return WritingAgent._cap_excessive_global_citation_density(updated)

    @staticmethod
    def _cap_excessive_global_citation_density(
        manuscript: str,
        *,
        max_per_1000_words: float = PUBLICATION_CITATION_MAX_DENSITY_PER_1000,
        min_word_count: int = PUBLICATION_CITATION_DENSITY_MIN_WORDS,
    ) -> str:
        """Remove redundant non-numeric citation markers when the whole manuscript is overcited."""
        raw = str(manuscript or "")
        main = WritingAgent._main_text_before_reference_section(raw)
        tail = raw[len(main):]
        word_count = main_publication_word_count(main)
        if word_count < min_word_count:
            return manuscript
        current = main
        while True:
            current_word_count = main_publication_word_count(current)
            max_citation_numbers = max(1, math.floor(current_word_count * max_per_1000_words / 1000))
            if len(WritingAgent._citation_numbers_from_text(current)) <= max_citation_numbers:
                break
            matches = list(re.finditer(r"[\[［][0-9\s,，、;；\-–—至]+[\]］]", current))
            candidates = WritingAgent._global_citation_removal_candidates(current, matches)
            if not candidates:
                break
            match = candidates[0]
            current = current[:match.start()] + current[match.end():]
            current = re.sub(r"\s+([.,;:!?。！？])", r"\1", current)
            current = re.sub(r"[ \t]{2,}", " ", current)
        return current + tail

    @staticmethod
    def _global_citation_removal_candidates(
        main_text: str,
        matches: list[re.Match[str]],
    ) -> list[re.Match[str]]:
        if not matches:
            return []
        all_numbers = WritingAgent._citation_numbers_from_text(main_text)
        number_frequency = {number: all_numbers.count(number) for number in set(all_numbers)}
        scored: list[tuple[int, int, int, int, re.Match[str]]] = []
        for match in matches:
            if WritingAgent._citation_marker_is_in_protected_numeric_context(main_text, match.start(), match.end()):
                continue
            if WritingAgent._citation_marker_is_in_protected_methodology_context(main_text, match.start(), match.end()):
                continue
            if WritingAgent._citation_marker_is_on_uncitable_line(main_text, match.start()):
                continue
            if WritingAgent._citation_marker_is_required_section_anchor(main_text, match.start(), match.end()):
                continue
            numbers = WritingAgent._dedupe_numbers(WritingAgent._citation_numbers_from_text(match.group(0)))
            if not numbers:
                continue
            repeated_elsewhere = all(number_frequency.get(number, 0) > 1 for number in numbers)
            if not repeated_elsewhere:
                continue
            heading = WritingAgent._section_heading_at_offset(main_text, match.start()).lower()
            section_priority = {
                "methods": 0,
                "方法": 0,
                "results": 1,
                "结果": 1,
                "discussion": 2,
                "讨论": 2,
                "conclusion": 3,
                "结论": 3,
                "introduction": 4,
                "引言": 4,
                "abstract": 5,
                "摘要": 5,
            }.get(heading, 6)
            max_frequency = max(number_frequency.get(number, 0) for number in numbers)
            scored.append((section_priority, len(numbers), -max_frequency, match.start(), match))
        scored.sort(key=lambda item: item[:4])
        return [item[4] for item in scored]

    @staticmethod
    def _cap_dominant_primary_trial_citations(
        manuscript: str,
        entries: list[dict[str, object]],
        *,
        max_mentions: int = 5,
    ) -> str:
        """Keep citation backfill from making one primary trial look like a universal source."""
        primary_numbers = set(WritingAgent._numeric_effect_source_reference_numbers(entries))
        if not primary_numbers:
            return manuscript
        entries_by_number = {
            int(item.get("number", 0) or 0): str(item.get("text") or "")
            for item in entries
            if int(item.get("number", 0) or 0) > 0
        }
        raw = str(manuscript or "")
        main = WritingAgent._main_text_before_reference_section(raw)
        tail = raw[len(main):]
        counts = {
            number: WritingAgent._citation_numbers_from_text(main).count(number)
            for number in primary_numbers
        }
        remaining_citation_numbers = len(WritingAgent._citation_numbers_from_text(main))
        word_count = WritingAgent._main_manuscript_word_count(main)
        minimum_citation_numbers = (
            math.ceil(word_count * PUBLICATION_CITATION_DENSITY_PER_1000 / 1000)
            if word_count >= PUBLICATION_CITATION_DENSITY_MIN_WORDS else 0
        )
        overused = {number for number, count in counts.items() if count > max_mentions}
        if not overused:
            return manuscript

        citation_pattern = r"[\[［][0-9\s,，、;；\-–—至]+[\]］]"
        pieces: list[str] = []
        cursor = 0
        changed = False
        for match in re.finditer(citation_pattern, main):
            marker = match.group(0)
            numbers = WritingAgent._dedupe_numbers(WritingAgent._citation_numbers_from_text(marker))
            removable = [
                number for number in numbers
                if number in overused and counts.get(number, 0) > max_mentions
            ]
            is_generic_single_primary = WritingAgent._citation_marker_is_generic_single_primary_source(
                main,
                match.start(),
                match.end(),
                marker,
                entries_by_number,
                primary_numbers,
            )
            if (
                not removable
                or WritingAgent._citation_marker_is_on_uncitable_line(main, match.start())
                or (
                    WritingAgent._citation_marker_is_in_strict_primary_source_context(main, match.start(), match.end())
                    and not is_generic_single_primary
                )
            ):
                pieces.append(main[cursor:match.end()])
                cursor = match.end()
                continue

            kept_numbers: list[int] = []
            for number in numbers:
                if number in removable and counts.get(number, 0) > max_mentions:
                    if minimum_citation_numbers and remaining_citation_numbers - 1 < minimum_citation_numbers:
                        kept_numbers.append(number)
                        continue
                    counts[number] = counts.get(number, 0) - 1
                    remaining_citation_numbers -= 1
                    changed = True
                    continue
                kept_numbers.append(number)
            replacement = WritingAgent._citation_cluster(kept_numbers)
            if replacement:
                replacement = WritingAgent._display_citation_for_text(replacement, marker)
            pieces.append(main[cursor:match.start()])
            pieces.append(replacement)
            cursor = match.end()

        if not changed:
            return manuscript
        pieces.append(main[cursor:])
        updated_main = "".join(pieces)
        updated_main = re.sub(r"\s+([.,;:!?。！？])", r"\1", updated_main)
        updated_main = re.sub(r"[ \t]{2,}", " ", updated_main)
        return updated_main + tail

    @staticmethod
    def _cap_dominant_primary_trial_citations_from_references(manuscript: str) -> str:
        entries = WritingAgent._reference_entries_from_references_section(manuscript)
        if not entries:
            return manuscript
        capped = WritingAgent._cap_dominant_primary_trial_citations(manuscript, entries)
        return WritingAgent._cap_overused_nonmethod_citations(capped, entries)

    @staticmethod
    def _cap_overused_nonmethod_citations(
        manuscript: str,
        entries: list[dict[str, object]],
        *,
        max_mentions: int = 5,
    ) -> str:
        """Avoid letting one background or comparator source become a universal citation."""
        if not entries:
            return manuscript
        entries_by_number = {
            int(item.get("number", 0) or 0): str(item.get("text") or "")
            for item in entries
            if int(item.get("number", 0) or 0) > 0
        }
        primary_numbers = set(WritingAgent._numeric_effect_source_reference_numbers(entries))
        method_numbers = set(
            WritingAgent._reference_numbers_matching(
                entries,
                (
                    "prisma", "cochrane", "rob 2", "risk-of-bias", "risk of bias",
                    "grade", "dersimonian", "laird", "heterogeneity", "i²", "i2",
                    "egger", "funnel", "publication bias", "bias in meta-analysis",
                ),
            )
        )
        raw = str(manuscript or "")
        main = WritingAgent._main_text_before_reference_section(raw)
        tail = raw[len(main):]
        counts = Counter(WritingAgent._citation_numbers_from_text(main))
        remaining_citation_numbers = len(WritingAgent._citation_numbers_from_text(main))
        word_count = WritingAgent._main_manuscript_word_count(main)
        minimum_citation_numbers = (
            math.ceil(word_count * PUBLICATION_CITATION_DENSITY_PER_1000 / 1000)
            if word_count >= PUBLICATION_CITATION_DENSITY_MIN_WORDS else 0
        )
        overused = {
            int(number)
            for number, count in counts.items()
            if int(number) not in method_numbers and count > max_mentions
        }
        if not overused:
            return manuscript

        pieces: list[str] = []
        cursor = 0
        changed = False
        citation_pattern = r"[\[［][0-9\s,，、;；\-–—至]+[\]］]"
        for match in re.finditer(citation_pattern, main):
            marker = match.group(0)
            numbers = WritingAgent._dedupe_numbers(WritingAgent._citation_numbers_from_text(marker))
            removable = [
                number for number in numbers
                if number in overused and counts.get(number, 0) > max_mentions
            ]
            is_generic_single_primary = WritingAgent._citation_marker_is_generic_single_primary_source(
                main,
                match.start(),
                match.end(),
                marker,
                entries_by_number,
                primary_numbers,
            )
            if (
                not removable
                or WritingAgent._citation_marker_is_on_uncitable_line(main, match.start())
                or (
                    WritingAgent._citation_marker_is_in_strict_primary_source_context(main, match.start(), match.end())
                    and not is_generic_single_primary
                )
                or WritingAgent._citation_marker_is_in_protected_methodology_context(main, match.start(), match.end())
            ):
                pieces.append(main[cursor:match.end()])
                cursor = match.end()
                continue

            kept_numbers: list[int] = []
            for number in numbers:
                if number in removable and counts.get(number, 0) > max_mentions:
                    if minimum_citation_numbers and remaining_citation_numbers - 1 < minimum_citation_numbers:
                        kept_numbers.append(number)
                        continue
                    counts[number] = counts.get(number, 0) - 1
                    remaining_citation_numbers -= 1
                    changed = True
                    continue
                kept_numbers.append(number)
            replacement = WritingAgent._citation_cluster(kept_numbers)
            if replacement:
                replacement = WritingAgent._display_citation_for_text(replacement, marker)
            pieces.append(main[cursor:match.start()])
            pieces.append(replacement)
            cursor = match.end()

        if not changed:
            return manuscript
        pieces.append(main[cursor:])
        updated_main = "".join(pieces)
        updated_main = re.sub(r"\s+([.,;:!?。！？])", r"\1", updated_main)
        updated_main = re.sub(r"[ \t]{2,}", " ", updated_main)
        return updated_main + tail

    @staticmethod
    def _sentence_around_offset(text: str, start: int, end: int) -> str:
        raw = str(text or "")
        left_candidates = [
            raw.rfind(".", 0, start),
            raw.rfind("。", 0, start),
            raw.rfind("!", 0, start),
            raw.rfind("！", 0, start),
            raw.rfind("?", 0, start),
            raw.rfind("？", 0, start),
            raw.rfind("\n", 0, start),
        ]
        sentence_start = max(left_candidates) + 1
        right_positions = [
            pos for pos in (
                raw.find(".", end),
                raw.find("。", end),
                raw.find("!", end),
                raw.find("！", end),
                raw.find("?", end),
                raw.find("？", end),
                raw.find("\n", end),
            )
            if pos >= 0
        ]
        sentence_end = min(right_positions) + 1 if right_positions else len(raw)
        return raw[sentence_start:sentence_end]

    @staticmethod
    def _citation_marker_is_generic_single_primary_source(
        text: str,
        start: int,
        end: int,
        marker: str,
        entries_by_number: dict[int, str],
        primary_numbers: set[int],
    ) -> bool:
        """Identify a single trial citation attached to an aggregate or generic claim."""
        numbers = WritingAgent._dedupe_numbers(WritingAgent._citation_numbers_from_text(marker))
        if len(numbers) != 1 or numbers[0] not in primary_numbers:
            return False
        sentence = WritingAgent._sentence_around_offset(text, start, end)
        reference_text = entries_by_number.get(numbers[0], "")
        if WritingAgent._sentence_mentions_reference_anchor(sentence, reference_text):
            return False
        sentence_lower = re.sub(r"\s+", " ", sentence).strip().lower()
        if not sentence_lower:
            return False
        generic_markers = (
            "pooled", "summary", "combined", "primary-analysis", "primary analysis",
            "selected trial", "selected primary", "across", "aggregate", "certainty",
            "grade", "source-verification", "source verification", "registry",
            "living-data", "living data", "non-primary", "leave-one-out",
            "sensitivity", "baseline risk", "absolute effect", "absolute benefit",
            "all primary", "trial-level", "documentation", "evidence profile",
            "合并", "主要分析", "选定", "总体", "汇总", "确定性", "GRADE",
            "敏感性", "基线风险", "绝对效应", "绝对获益", "来源", "登记",
        )
        return (
            any(marker_text in sentence_lower for marker_text in generic_markers)
            or WritingAgent._sentence_has_numeric_effect_claim(sentence)
            or WritingAgent._sentence_has_primary_trial_count_claim(sentence)
        )

    @staticmethod
    def _citation_marker_is_in_strict_primary_source_context(text: str, start: int, end: int) -> bool:
        """Protect citations that support concrete numeric or trial-count statements."""
        sentence = WritingAgent._sentence_around_offset(text, start, end)
        if WritingAgent._sentence_has_numeric_effect_claim(sentence):
            return True
        if WritingAgent._sentence_has_primary_trial_count_claim(sentence):
            return True
        if re.search(r"\b(?:events?|deaths?|total|participants?)\b.{0,40}\b\d+\s*/\s*\d+", sentence, flags=re.I):
            return True
        return False

    @staticmethod
    def _citation_marker_is_in_protected_methodology_context(text: str, start: int, end: int) -> bool:
        heading = WritingAgent._section_heading_at_offset(text, start).lower()
        if heading not in {"methods", "方法"}:
            return False
        raw = str(text or "")
        left = max(
            raw.rfind(".", 0, start),
            raw.rfind("。", 0, start),
            raw.rfind("!", 0, start),
            raw.rfind("！", 0, start),
            raw.rfind("?", 0, start),
            raw.rfind("？", 0, start),
            raw.rfind("\n\n", 0, start),
        )
        right_candidates = [
            pos for pos in (
                raw.find(".", end),
                raw.find("。", end),
                raw.find("!", end),
                raw.find("！", end),
                raw.find("?", end),
                raw.find("？", end),
                raw.find("\n\n", end),
            )
            if pos >= 0
        ]
        right = min(right_candidates) if right_candidates else min(len(raw), end + 240)
        sentence = raw[left + 1:right + 1].lower()
        protected_terms = (
            "prisma",
            "i2 statistic", "i² statistic", "i2", "i²",
            "tau2", "tau²", "cochran",
            "heterogeneity statistic", "heterogeneity statistics",
            "grade describes", "grade described", "grade domains", "grade certainty",
            "grade asks", "body of evidence", "confidence a decision maker",
            "risk-of-bias judgments", "risk of bias judgments",
            "rob 2", "cochrane",
            "dersimonian", "laird",
            "egger", "funnel", "publication bias",
            "inverse-variance", "inverse variance",
            "random-effects model", "random effects model",
            "fixed-effect model", "fixed effect model",
            "prisma 2020", "prisma-s",
            "报告遵循", "异质性统计", "i2统计", "i²统计", "tau2", "tau²",
            "grade描述", "grade确定性", "偏倚风险判断", "rob 2",
            "发表偏倚", "漏斗图", "随机效应模型", "固定效应模型",
        )
        return any(term in sentence for term in protected_terms)

    @staticmethod
    def _citation_marker_is_on_uncitable_line(text: str, start: int) -> bool:
        raw = str(text or "")
        line_start = raw.rfind("\n", 0, start) + 1
        line_end = raw.find("\n", start)
        if line_end < 0:
            line_end = len(raw)
        stripped = raw[line_start:line_end].strip()
        return bool(
            not stripped
            or stripped.startswith("#")
            or stripped.startswith("|")
            or stripped.startswith("![")
            or stripped.startswith("```")
        )

    @staticmethod
    def _section_heading_at_offset(text: str, offset: int) -> str:
        heading = ""
        for match in re.finditer(r"^##\s+(.+?)\s*$", str(text or ""), flags=re.M):
            if match.start() > offset:
                break
            heading = match.group(1).strip()
        return heading

    @staticmethod
    def _citation_marker_is_required_section_anchor(text: str, start: int, end: int) -> bool:
        raw = str(text or "")
        section = WritingAgent._section_span_at_offset(raw, start)
        if section is None:
            return False
        heading, body_start, body_end = section
        body = raw[body_start:body_end]
        minimum = WritingAgent._minimum_citation_anchors_for_heading(heading, [{"number": index} for index in range(1, 24)])
        if WritingAgent._citation_anchor_count(body) > minimum:
            return False
        paragraph_start = raw.rfind("\n\n", 0, start)
        paragraph_start = body_start if paragraph_start < body_start else paragraph_start + 2
        paragraph_end = raw.find("\n\n", end)
        if paragraph_end < 0 or paragraph_end > body_end:
            paragraph_end = body_end
        paragraph = raw[paragraph_start:paragraph_end]
        return bool(WritingAgent._citation_numbers_from_text(paragraph))

    @staticmethod
    def _section_span_at_offset(text: str, offset: int) -> tuple[str, int, int] | None:
        matches = list(re.finditer(r"^##\s+(.+?)\s*$", str(text or ""), flags=re.M))
        current: re.Match[str] | None = None
        next_match: re.Match[str] | None = None
        for index, match in enumerate(matches):
            if match.start() <= offset:
                current = match
                next_match = matches[index + 1] if index + 1 < len(matches) else None
            elif match.start() > offset:
                break
        if current is None:
            return None
        return current.group(1).strip(), current.end(), next_match.start() if next_match else len(text)

    @staticmethod
    def _smooth_mechanical_citation_density_paragraph(paragraph: str) -> str:
        raw = str(paragraph or "")
        if not raw.strip() or not WritingAgent._paragraph_has_citable_line(raw):
            return paragraph
        citation_pattern = r"[\[［][0-9\s,，、;；\-–—至]+[\]］]"

        def density_snapshot(text: str) -> tuple[list[re.Match[str]], int, float]:
            matches = list(re.finditer(citation_pattern, text))
            without_citations = re.sub(citation_pattern, " ", text)
            text_units = WritingAgent._text_unit_count(without_citations)
            markers_per_35 = round(len(matches) * 35 / text_units, 2) if text_units else 0.0
            return matches, text_units, markers_per_35

        current = raw
        while True:
            matches, text_units, markers_per_35 = density_snapshot(current)
            if (
                len(matches) < PUBLICATION_CITATION_MECHANICAL_MIN_MARKERS
                or text_units < PUBLICATION_CITATION_MIN_SUBSTANTIAL_PARAGRAPH_WORDS
                or markers_per_35 <= PUBLICATION_CITATION_MECHANICAL_MAX_MARKERS_PER_35_UNITS
            ):
                break
            candidates = WritingAgent._mechanical_citation_removal_candidates(current, matches)
            if not candidates:
                break
            candidate = candidates[0]
            current = current[:candidate.start()] + current[candidate.end():]
            current = re.sub(r"\s+([.,;:!?。！？])", r"\1", current)
            current = re.sub(r"[ \t]{2,}", " ", current)
        return current

    @staticmethod
    def _mechanical_citation_removal_candidates(
        paragraph: str,
        matches: list[re.Match[str]],
    ) -> list[re.Match[str]]:
        marker_numbers = [
            WritingAgent._dedupe_numbers(WritingAgent._citation_numbers_from_text(match.group(0)))
            for match in matches
        ]
        protected = [
            WritingAgent._citation_marker_is_in_protected_numeric_context(paragraph, match.start(), match.end())
            for match in matches
        ]
        scored: list[tuple[int, int, re.Match[str]]] = []
        for index, match in enumerate(matches):
            if protected[index]:
                continue
            numbers = set(marker_numbers[index])
            if not numbers:
                continue
            other_numbers = set()
            for other_index, other in enumerate(marker_numbers):
                if other_index != index:
                    other_numbers.update(other)
            is_middle = 0 < index < len(matches) - 1
            subset_elsewhere = numbers <= other_numbers
            overlaps_elsewhere = bool(numbers & other_numbers)
            if subset_elsewhere:
                priority = 0
            elif overlaps_elsewhere and is_middle:
                priority = 1
            elif is_middle:
                priority = 2
            else:
                priority = 3
            scored.append((priority, len(numbers), match))
        scored.sort(key=lambda item: (item[0], item[1]))
        return [item[2] for item in scored if item[0] < 4]

    @staticmethod
    def _limit_repeated_large_citation_clusters(
        manuscript: str,
        *,
        max_repeats: int = 1,
        large_cluster_size: int = 3,
        replacement_pool: list[int] | None = None,
    ) -> str:
        """Avoid repeatedly pasting the same broad citation bundle into many paragraphs."""
        raw = str(manuscript or "")
        reference_match = WritingAgent._reference_heading_match(raw)
        main = raw[: reference_match.start()] if reference_match else raw
        tail = raw[reference_match.start():] if reference_match else ""
        seen: dict[tuple[int, ...], int] = {}
        # Keep replacement semantically local: repeated broad clusters may be narrowed,
        # but must not be rotated to unrelated references from the global pool.
        remaining_citation_numbers = len(WritingAgent._citation_numbers_from_text(main))
        minimum_citation_numbers = 0
        if replacement_pool is not None:
            word_count = WritingAgent._main_manuscript_word_count(main)
            if word_count >= PUBLICATION_CITATION_DENSITY_MIN_WORDS:
                minimum_citation_numbers = max(
                    1,
                    math.ceil(word_count * PUBLICATION_CITATION_DENSITY_PER_1000 / 1000) + 5,
                )

        def replace(match: re.Match[str]) -> str:
            nonlocal remaining_citation_numbers
            marker = match.group(0)
            numbers = WritingAgent._dedupe_numbers(WritingAgent._citation_numbers_from_text(marker))
            if len(numbers) < large_cluster_size:
                return marker
            key = tuple(numbers)
            seen[key] = seen.get(key, 0) + 1
            if seen[key] <= max_repeats:
                return marker
            if WritingAgent._citation_marker_is_in_protected_numeric_context(main, match.start(), match.end()):
                narrowed = numbers[:2] if len(numbers) > 2 else numbers
                if len(narrowed) == len(numbers):
                    return marker
                if (
                    minimum_citation_numbers
                    and remaining_citation_numbers - (len(numbers) - len(narrowed)) < minimum_citation_numbers
                ):
                    return marker
                remaining_citation_numbers -= len(numbers) - len(narrowed)
                citation = WritingAgent._citation_cluster(narrowed)
                return WritingAgent._display_citation_for_text(citation, marker)
            offset = ((seen[key] - max_repeats - 1) * 2) % len(numbers)
            narrowed = [numbers[offset]]
            if len(numbers) > 1:
                narrowed.append(numbers[(offset + 1) % len(numbers)])
            if (
                minimum_citation_numbers
                and remaining_citation_numbers - (len(numbers) - len(narrowed)) < minimum_citation_numbers
            ):
                replacement = WritingAgent._same_size_replacement_citation_numbers(
                    numbers,
                    replacement_pool,
                    occurrence_index=seen[key] - max_repeats,
                )
                if replacement:
                    citation = WritingAgent._citation_cluster(replacement)
                    return WritingAgent._display_citation_for_text(citation, marker)
                return marker
            remaining_citation_numbers -= len(numbers) - len(narrowed)
            citation = WritingAgent._citation_cluster(narrowed)
            return WritingAgent._display_citation_for_text(citation, marker)

        narrowed_main = re.sub(
            r"[\[［][0-9\s,，、;；\-–—至]+[\]］]",
            replace,
            main,
        )
        return narrowed_main + tail

    @staticmethod
    def _same_size_replacement_citation_numbers(
        numbers: list[int],
        replacement_pool: list[int] | None,
        *,
        occurrence_index: int = 1,
    ) -> list[int]:
        """Return a different citation bundle of the same size when density must be preserved."""
        size = len(numbers)
        if size <= 0 or not replacement_pool:
            return []
        pool = WritingAgent._dedupe_numbers([int(number) for number in replacement_pool if int(number) > 0])
        if len(pool) < size:
            return []
        original = tuple(sorted(numbers))
        start = max(0, occurrence_index - 1) * size
        for shift in range(len(pool)):
            offset = (start + shift) % len(pool)
            candidate = [pool[(offset + idx) % len(pool)] for idx in range(size)]
            candidate = sorted(set(candidate))
            if len(candidate) != size:
                continue
            if tuple(candidate) == original:
                continue
            return candidate
        return []

    @staticmethod
    def _citation_marker_is_in_protected_numeric_context(text: str, start: int, end: int) -> bool:
        """Do not narrow citations attached to numeric effect, sample-size, or absolute-effect claims."""
        raw = str(text or "")
        left_candidates = [
            raw.rfind(".", 0, start),
            raw.rfind("。", 0, start),
            raw.rfind("!", 0, start),
            raw.rfind("！", 0, start),
            raw.rfind("?", 0, start),
            raw.rfind("？", 0, start),
            raw.rfind("\n", 0, start),
        ]
        sentence_start = max(left_candidates) + 1
        right_positions = [
            pos for pos in (
                raw.find(".", end),
                raw.find("。", end),
                raw.find("!", end),
                raw.find("！", end),
                raw.find("?", end),
                raw.find("？", end),
                raw.find("\n", end),
            )
            if pos >= 0
        ]
        sentence_end = min(right_positions) + 1 if right_positions else len(raw)
        sentence = raw[sentence_start:sentence_end]
        lowered = sentence.lower()
        absolute_terms = (
            "absolute risk difference", "number needed to treat", "nnt",
            "pooled hr", "pooled hazard ratio", "pooled effect",
            "绝对风险差", "需要治疗人数", "需治数", "获益需治数",
            "合并hr", "合并效应",
        )
        return bool(
            WritingAgent._sentence_has_numeric_effect_claim(sentence)
            or WritingAgent._sentence_has_primary_trial_count_claim(sentence)
            or WritingAgent._sentence_has_source_sensitive_result_claim(sentence)
            or any(term in lowered for term in absolute_terms)
        )

    @staticmethod
    def _sentence_has_source_sensitive_result_claim(sentence: str) -> bool:
        raw = str(sentence or "")
        patterns = [
            (
                r"\b(?:benefit|beneficial|event\s+reduction|fewer|reduc(?:e|es|ed|ing)|lower(?:s|ed|ing)?|"
                r"favou?red|improv(?:e|es|ed|ing)|show(?:s|ed|ing)?|suggest(?:s|ed|ing)?)\b"
                r".{0,110}\b(?:events?|hospitali[sz]ations?|mortality|death|risk|outcomes?|endpoints?)\b"
            ),
            (
                r"\b(?:preventable events?|baseline risk|absolute effects?|absolute benefit|absolute risk|"
                r"primary estimate|primary endpoint|secondary endpoint|duplicate reports?|focused PICO)\b"
            ),
            (
                r"\b(?:safety|harms?|tolerability|adverse\s+events?|discontinuations?)\b"
                r".{0,90}\b(?:higher|lower|similar|increased|reduced|fewer|more|risk)\b"
            ),
            (
                r"(?:获益|降低|减少|改善|显示|提示).{0,50}"
                r"(?:事件|住院|死亡|风险|结局|终点)"
            ),
            (
                r"(?:安全性|不良事件|耐受性|停药).{0,50}"
                r"(?:升高|增加|降低|减少|相似|更少|更多|风险)"
            ),
        ]
        return any(re.search(pattern, raw, flags=re.I) for pattern in patterns)

    @staticmethod
    def _merge_adjacent_citation_clusters(
        manuscript: str,
        *,
        max_cluster_size: int = 6,
        trim_overloaded: bool = False,
    ) -> str:
        """Collapse adjacent citation clusters created by layered backfills."""
        raw = str(manuscript or "")
        reference_match = WritingAgent._reference_heading_match(raw)
        main = raw[: reference_match.start()] if reference_match else raw
        tail = raw[reference_match.start():] if reference_match else ""
        citation_pattern = r"[\[［][0-9\s,，、;；\-–—至]+[\]］]"
        adjacent_pattern = re.compile(rf"({citation_pattern})\s*({citation_pattern})")

        previous = None
        merged = main
        while previous != merged:
            previous = merged

            def replace(match: re.Match[str]) -> str:
                left, right = match.group(1), match.group(2)
                numbers = WritingAgent._dedupe_numbers(
                    WritingAgent._citation_numbers_from_text(left)
                    + WritingAgent._citation_numbers_from_text(right)
                )
                numbers = sorted(numbers)
                max_size = max(1, int(max_cluster_size or 1))
                if len(numbers) > max_size:
                    if not trim_overloaded:
                        return match.group(0)
                    numbers = numbers[:max_size]
                citation = WritingAgent._citation_cluster(numbers)
                return WritingAgent._display_citation_for_text(citation, left + right)

            merged = adjacent_pattern.sub(replace, merged)
        return merged + tail

    @staticmethod
    def _dedupe_numbers(numbers: list[int]) -> list[int]:
        ordered: list[int] = []
        seen: set[int] = set()
        for number in numbers:
            if number <= 0 or number in seen:
                continue
            seen.add(number)
            ordered.append(number)
        return ordered

    @staticmethod
    def _reference_numbers_matching(entries: list[dict[str, object]], keywords: tuple[str, ...]) -> list[int]:
        matches: list[int] = []
        for item in entries:
            text = str(item.get("text") or "").lower()
            if any(keyword.lower() in text for keyword in keywords):
                number = int(item.get("number", 0) or 0)
                if number > 0 and number not in matches:
                    matches.append(number)
        return matches

    @staticmethod
    def _citation_for_reference_patterns(refs_text: str, patterns: list[str]) -> str:
        """Return a citation cluster for reference entries matching any pattern."""
        if not refs_text or not patterns:
            return ""
        numbers: list[int] = []
        entry_pattern = re.compile(
            r"^(?:\[(\d+)\]|［(\d+)］)\s+([\s\S]*?)(?=^(?:\[\d+\]|［\d+］)\s+|\Z)",
            flags=re.MULTILINE,
        )
        for match in entry_pattern.finditer(str(refs_text)):
            number = int(match.group(1) or match.group(2) or 0)
            if number <= 0:
                continue
            entry = match.group(0)
            if any(re.search(pattern, entry, flags=re.IGNORECASE) for pattern in patterns):
                numbers.append(number)
        return WritingAgent._citation_cluster(numbers)

    @staticmethod
    def _citation_cluster(reference_numbers: list[int]) -> str:
        numbers = sorted({number for number in reference_numbers if number > 0})
        if not numbers:
            return ""
        if len(numbers) == 1:
            return f"[{numbers[0]}]"
        if len(numbers) == 2:
            return f"[{numbers[0]},{numbers[1]}]"
        parts: list[str] = []
        start = prev = numbers[0]
        for number in numbers[1:] + [None]:
            if number == prev + 1:
                prev = number
                continue
            if prev - start >= 2:
                parts.append(f"{start}-{prev}")
            elif prev > start:
                parts.extend([str(start), str(prev)])
            else:
                parts.append(str(start))
            if number is not None:
                start = prev = number
        return "[" + ",".join(parts) + "]"

    @staticmethod
    def _ensure_section_has_citation(manuscript: str, heading: str, citation: str) -> str:
        if not citation:
            return manuscript
        pattern = rf"(^##\s+{re.escape(heading)}\s*$)([\s\S]*?)(?=^##\s+|\Z)"
        match = re.search(pattern, manuscript, flags=re.M)
        if not match:
            return manuscript
        body = match.group(2)
        if WritingAgent._citation_numbers_from_text(body):
            return manuscript
        updated_body = WritingAgent._append_citation_to_first_paragraph(body, citation, heading=heading)
        if updated_body == body:
            return manuscript
        return manuscript[:match.start(2)] + updated_body + manuscript[match.end(2):]

    @staticmethod
    def _ensure_section_has_source_type_citation(manuscript: str, heading: str, citation: str) -> str:
        if not citation:
            return manuscript
        pattern = rf"(^##\s+{re.escape(heading)}\s*$)([\s\S]*?)(?=^##\s+|\Z)"
        match = re.search(pattern, manuscript, flags=re.M)
        if not match:
            return manuscript
        body = match.group(2)
        existing_numbers = set(WritingAgent._citation_numbers_from_text(body))
        target_numbers = set(WritingAgent._citation_numbers_from_text(citation))
        if not existing_numbers or not target_numbers or existing_numbers & target_numbers:
            return manuscript
        updated_body = WritingAgent._append_citation_to_first_paragraph(body, citation, heading=heading)
        if updated_body == body:
            return manuscript
        return manuscript[:match.start(2)] + updated_body + manuscript[match.end(2):]

    @staticmethod
    def _ensure_section_has_citation_anchor_count(
        manuscript: str,
        heading: str,
        citation: str,
        minimum_anchors: int,
    ) -> str:
        if not citation or minimum_anchors <= 1:
            return manuscript
        pattern = rf"(^##\s+{re.escape(heading)}\s*$)([\s\S]*?)(?=^##\s+|\Z)"
        match = re.search(pattern, manuscript, flags=re.M)
        if not match:
            return manuscript
        body = match.group(2)
        current = WritingAgent._citation_anchor_count(body)
        if current >= minimum_anchors:
            return manuscript

        parts = re.split(r"(\n\s*\n)", body)
        for index in range(0, len(parts), 2):
            if current >= minimum_anchors:
                break
            paragraph = parts[index]
            if (
                not WritingAgent._paragraph_has_citable_line(paragraph)
                or WritingAgent._citation_numbers_from_text(paragraph)
            ):
                continue
            updated_paragraph = WritingAgent._append_citation_to_first_paragraph(paragraph, citation, heading=heading)
            if updated_paragraph != paragraph:
                parts[index] = updated_paragraph
                current += 1

        updated_body = "".join(parts)
        if updated_body == body:
            return manuscript
        return manuscript[:match.start(2)] + updated_body + manuscript[match.end(2):]

    @staticmethod
    def _ensure_interpretive_section_citation_paragraph_coverage(
        manuscript: str,
        heading: str,
        citation: str,
        *,
        minimum_rate: float = PUBLICATION_INTERPRETIVE_CITED_PARAGRAPH_RATE,
    ) -> str:
        if not citation:
            return manuscript
        pattern = rf"(^##\s+{re.escape(heading)}\s*$)([\s\S]*?)(?=^##\s+|\Z)"
        match = re.search(pattern, manuscript, flags=re.M)
        if not match:
            return manuscript
        body = match.group(2)
        parts = re.split(r"(\n\s*\n)", body)
        substantial_indices: list[int] = []
        cited_indices: set[int] = set()
        for index in range(0, len(parts), 2):
            paragraph = parts[index]
            if not WritingAgent._paragraph_has_citable_line(paragraph):
                continue
            paragraph_without_citations = re.sub(r"[\[［][0-9\s,，、;；\-–—至]+[\]］]", " ", paragraph)
            if WritingAgent._text_unit_count(paragraph_without_citations) < PUBLICATION_CITATION_MIN_SUBSTANTIAL_PARAGRAPH_WORDS:
                continue
            substantial_indices.append(index)
            if WritingAgent._citation_numbers_from_text(paragraph):
                cited_indices.add(index)
        if len(substantial_indices) < 2:
            return manuscript

        target_cited = min(len(substantial_indices), math.ceil(len(substantial_indices) * minimum_rate))
        if len(cited_indices) >= target_cited:
            return manuscript
        for index in substantial_indices:
            if len(cited_indices) >= target_cited:
                break
            if index in cited_indices:
                continue
            updated_paragraph = WritingAgent._append_citation_to_first_paragraph(parts[index], citation, heading=heading)
            if updated_paragraph != parts[index]:
                parts[index] = updated_paragraph
                cited_indices.add(index)
        updated_body = "".join(parts)
        if updated_body == body:
            return manuscript
        return manuscript[:match.start(2)] + updated_body + manuscript[match.end(2):]

    @staticmethod
    def _append_citation_to_least_cited_paragraph(
        manuscript: str,
        heading: str,
        citation: str,
        *,
        entries: list[dict[str, object]] | None = None,
        used_numbers: set[int] | None = None,
        need_unique: bool = False,
    ) -> str:
        if not citation:
            return manuscript
        pattern = rf"(^##\s+{re.escape(heading)}\s*$)([\s\S]*?)(?=^##\s+|\Z)"
        match = re.search(pattern, manuscript, flags=re.M)
        if not match:
            return manuscript
        body = match.group(2)
        target_numbers = set(WritingAgent._citation_numbers_from_text(citation))
        if not target_numbers:
            return manuscript

        parts = re.split(r"(\n\s*\n)", body)
        best_index: int | None = None
        best_score: tuple[int, int] | None = None
        for index in range(0, len(parts), 2):
            paragraph = parts[index]
            if not WritingAgent._paragraph_has_citable_line(paragraph):
                continue
            if WritingAgent._paragraph_should_avoid_inline_citation_backfill(paragraph, heading=heading):
                continue
            paragraph_numbers = set(WritingAgent._citation_numbers_from_text(paragraph))
            if target_numbers and target_numbers.issubset(paragraph_numbers):
                continue
            # Prefer paragraphs with fewer citation numbers, then shorter paragraphs,
            # so density backfill is distributed instead of repeatedly piling onto
            # the opening sentence.
            score = (len(paragraph_numbers), len(paragraph))
            if best_score is None or score < best_score:
                best_index = index
                best_score = score

        if best_index is None:
            return manuscript
        paragraph_citation = WritingAgent._claim_specific_citation_for_paragraph(
            parts[best_index],
            entries,
            heading,
            citation,
            used_numbers=used_numbers,
            need_unique=need_unique,
        )
        updated_paragraph = WritingAgent._append_citation_to_first_paragraph(
            parts[best_index],
            paragraph_citation,
            heading=heading,
        )
        if updated_paragraph == parts[best_index]:
            return manuscript
        parts[best_index] = updated_paragraph
        updated_body = "".join(parts)
        return manuscript[:match.start(2)] + updated_body + manuscript[match.end(2):]

    @staticmethod
    def _citation_anchor_count(body: str) -> int:
        count = 0
        for paragraph in re.split(r"\n\s*\n", str(body or "")):
            if WritingAgent._paragraph_has_citable_line(paragraph) and WritingAgent._citation_numbers_from_text(paragraph):
                count += 1
        return count

    @staticmethod
    def _paragraph_has_citable_line(paragraph: str) -> bool:
        if "```" in str(paragraph or ""):
            return False
        for line in str(paragraph or "").splitlines():
            stripped = line.strip()
            if (
                not stripped
                or stripped.startswith("#")
                or stripped.startswith("|")
                or stripped.startswith("![")
                or re.match(r"^[-*]\s+", stripped)
            ):
                continue
            return True
        return False

    @staticmethod
    def _text_unit_count(text: str) -> int:
        return len(re.findall(r"[A-Za-z0-9]+(?:[-'][A-Za-z0-9]+)?|[\u4e00-\u9fff]|[%./+-]+", str(text or "")))

    @staticmethod
    def _citation_numbers_from_text(text: str) -> list[int]:
        numbers: list[int] = []
        for match in re.finditer(r"[\[［]([0-9\s,，、;；\-–—至]+)[\]］]", str(text or "")):
            token = match.group(1)
            for part in re.split(r"\s*(?:,|，|、|;|；)\s*", token):
                if re.search(r"[-–—]|至", part):
                    bounds = [item.strip() for item in re.split(r"[-–—]|至", part, maxsplit=1)]
                    if len(bounds) != 2 or not bounds[0].isdigit() or not bounds[1].isdigit():
                        continue
                    start, end = int(bounds[0]), int(bounds[1])
                    if end >= start:
                        numbers.extend(range(start, end + 1))
                elif part.strip().isdigit():
                    numbers.append(int(part.strip()))
        return numbers

    @staticmethod
    def _append_citation_to_first_paragraph(body: str, citation: str, *, heading: str = "") -> str:
        parts = re.split(r"(\n\s*\n)", body)
        if not parts:
            return body
        for part_index in range(0, len(parts), 2):
            paragraph = parts[part_index]
            if not paragraph.strip():
                continue
            if WritingAgent._paragraph_should_avoid_inline_citation_backfill(paragraph, heading=heading):
                continue
            lines = paragraph.splitlines()
            for index, line in enumerate(lines):
                stripped = line.strip()
                if not stripped or stripped.startswith("#") or stripped.startswith("|") or re.match(r"^[-*]\s+", stripped):
                    continue
                lines[index] = WritingAgent._append_citation_to_sentence(line, citation)
                parts[part_index] = "\n".join(lines)
                return "".join(parts)
        return body

    @staticmethod
    def _paragraph_should_avoid_inline_citation_backfill(paragraph: str, *, heading: str = "") -> bool:
        """Avoid attaching trial citations to PRISMA counts or internal table/figure prose."""
        raw = re.sub(r"\s+", " ", str(paragraph or "")).strip()
        if not raw:
            return True
        heading_lower = str(heading or "").strip().lower()
        raw_lower = raw.lower()
        if heading_lower not in {"results", "结果"}:
            return False
        if any(marker in raw_lower for marker in (
            "the search identified",
            "records remained for screening",
            "title/abstract",
            "full-text records were assessed",
            "prisma flow",
            "prisma流程",
            "检索共识别",
            "去重后",
            "题名/摘要",
            "全文评估",
        )):
            return True
        if any(marker in raw_lower for marker in (
            "table 1 lists",
            "table 2",
            "table 3",
            "table 4",
            "forest plot and table",
            "the plot emphasizes",
            "图1",
            "图2",
            "图3",
            "表1",
            "表2",
            "表3",
            "表4",
        )):
            return not (
                WritingAgent._sentence_has_numeric_effect_claim(raw)
                or WritingAgent._sentence_has_primary_trial_count_claim(raw)
            )
        return False

    @staticmethod
    def _append_citation_to_sentence(line: str, citation: str) -> str:
        trailing = line.rstrip()
        suffix = line[len(trailing):]
        display_citation = WritingAgent._display_citation_for_text(citation, trailing)
        if trailing.endswith(display_citation):
            return line
        if trailing.endswith((".", "。")):
            spacer = "" if display_citation.startswith("［") else " "
            return trailing[:-1].rstrip() + f"{spacer}{display_citation}" + trailing[-1] + suffix
        spacer = "" if display_citation.startswith("［") else " "
        return trailing + f"{spacer}{display_citation}" + suffix

    @staticmethod
    def _display_citation_for_text(citation: str, text: str) -> str:
        raw = str(citation or "")
        if not raw:
            return raw
        body = str(text or "")
        uses_full_width_citation = bool(re.search(r"［[0-9\s,，、;；\-–—至]+］", body))
        cjk_chars = len(re.findall(r"[\u4e00-\u9fff]", body))
        latin_words = len(re.findall(r"\b[A-Za-z][A-Za-z'-]*\b", body))
        if not uses_full_width_citation and cjk_chars <= latin_words:
            return raw
        match = re.fullmatch(r"\[([0-9,\-]+)\]", raw)
        if not match:
            return raw
        localized = match.group(1).replace(",", "，")
        return f"［{localized}］"

    @staticmethod
    def _normalize_citation_marker_style(manuscript: str, *, lang: str = "en") -> str:
        raw = str(manuscript or "")
        if str(lang or "").strip().lower() not in {"zh", "cn", "chinese", "中文"}:
            parts = re.split(r"(```[\s\S]*?```)", raw)

            def normalize_english_segment(segment: str) -> str:
                normalized_segment = re.sub(
                    r"(?<=[A-Za-z0-9%)\]])(?=\[[0-9][0-9,\s;\-–—]*\])",
                    " ",
                    segment,
                )
                normalized_segment = re.sub(
                    r"[ \t]{2,}(?=\[[0-9][0-9,\s;\-–—]*\])",
                    " ",
                    normalized_segment,
                )
                return normalized_segment

            return "".join(
                part if part.startswith("```") else normalize_english_segment(part)
                for part in parts
            )
        parts = re.split(r"(```[\s\S]*?```)", raw)

        def normalize_text_segment(segment: str) -> str:
            def replace(match: re.Match[str]) -> str:
                body = match.group(1)
                normalized = re.sub(r"\s+", "", body)
                normalized = normalized.replace("，", ",").replace("、", ",")
                normalized = normalized.replace(";", ",").replace("；", ",")
                normalized = normalized.replace(",", "，")
                return f"［{normalized}］"

            normalized_segment = re.sub(r"\[([0-9][0-9,\s;；、，\-–—]*)\]", replace, segment)
            normalized_segment = re.sub(
                r"(?<=[A-Za-z0-9\u4e00-\u9fff%）)])[ \t]+(?=［[0-9])",
                "",
                normalized_segment,
            )

            def ensure_terminal_punctuation(match: re.Match[str]) -> str:
                line = match.group(0)
                stripped = line.rstrip()
                suffix = line[len(stripped):]
                if stripped.endswith(("。", "！", "？", ".", "!", "?")):
                    return line
                return stripped + "。" + suffix

            return re.sub(
                r"(?m)^(?!\s*(?:#|\||!|\[|［\d+］)).*?［[0-9][0-9，、,;；\s\-–—至]+］[ \t]*$",
                ensure_terminal_punctuation,
                normalized_segment,
            )

        normalized_parts = [
            part if part.startswith("```") else normalize_text_segment(part)
            for part in parts
        ]
        return "".join(normalized_parts)

    @staticmethod
    def _backfill_after_fact_repair(manuscript: str) -> str:
        """Restore publication cross-references that fact repair may remove with process-framed text."""
        manuscript = WritingAgent._backfill_publication_figure_references(manuscript)
        manuscript = WritingAgent._backfill_publication_figure_legends(manuscript)
        manuscript = WritingAgent._backfill_publication_table_notes(manuscript)
        return manuscript

    @staticmethod
    def _backfill_publication_figure_references(manuscript: str) -> str:
        """Mention numbered figures in Results when figure captions exist but main text omits them."""
        figure_numbers = WritingAgent._defined_figure_numbers(manuscript)
        if not figure_numbers:
            return manuscript
        main_text = WritingAgent._main_text_before_figures(manuscript)
        mentioned = set(WritingAgent._numbered_label_refs(main_text, "Figure"))
        missing = [number for number in figure_numbers if number not in mentioned]
        if not missing:
            return manuscript
        zh = bool(re.search(r"^#{1,4}\s+图\s*\d+\b", manuscript, flags=re.M))
        label = WritingAgent._figure_reference_label_zh(missing) if zh else WritingAgent._figure_reference_label(missing)
        if zh:
            if set(missing) >= {1, 2, 3, 4}:
                sentence = "图1显示筛选流程，图2显示主要合并效应，图3显示偏倚风险概要，图4显示逐一剔除敏感性分析。"
            else:
                sentence = f"{label}显示与主要结果相关的图形信息。"
        else:
            sentence = (
                f"{label} provide additional graphical information for the primary result; the tabular estimates "
                "remain the numeric reference for effect size, precision, and study weight."
            )
        return WritingAgent._append_sentence_to_section(manuscript, "结果" if zh else "Results", sentence)

    @staticmethod
    def _backfill_publication_figure_legends(manuscript: str) -> str:
        """Add explanatory legends below numbered figures when only an image is present."""
        raw = str(manuscript or "")
        matches = list(re.finditer(r"^#{1,4}\s+(Figure|图)\s*(\d+)\.?\s*(.*)$", raw, flags=re.I | re.M))
        if not matches:
            return manuscript
        pieces: list[str] = []
        cursor = 0
        changed = False
        for index, match in enumerate(matches):
            end = len(raw)
            if index + 1 < len(matches):
                end = matches[index + 1].start()
            section_match = WritingAgent._publication_block_boundary_match(raw[match.end():end])
            if section_match:
                end = match.end() + section_match.start()
            block = raw[match.start():end]
            pieces.append(raw[cursor:match.start()])
            if WritingAgent._figure_block_has_legend(block):
                pieces.append(block)
            else:
                legend = WritingAgent._figure_legend_for_title(match.group(3), zh=match.group(1) == "图")
                separator = "\n" if block.endswith("\n") else "\n\n"
                pieces.append(block.rstrip() + separator + legend + "\n")
                changed = True
            cursor = end
        pieces.append(raw[cursor:])
        return "".join(pieces) if changed else manuscript

    @staticmethod
    def _figure_block_has_legend(block: str) -> bool:
        return bool(
            re.search(
                r"(^|\n)\s*(?:\*\*)?(?:Legend|Caption|Note|图注|说明)(?:\*\*)?\s*[:：.]",
                str(block or ""),
                flags=re.I,
            )
        )

    @staticmethod
    def _figure_legend_for_title(title: str, *, zh: bool = False) -> str:
        lowered = str(title or "").lower()
        if zh:
            if "prisma" in lowered or "流程" in str(title or "") or "flow" in lowered:
                return "图注：该流程图概述记录识别、去重、筛选、全文评估、排除原因以及纳入定性和定量综合的研究。"
            if "森林" in str(title or "") or "forest" in lowered:
                return "图注：森林图展示各研究效应量及其95%置信区间，并显示预设Meta分析模型得到的合并估计值。CI=置信区间。"
            if "敏感" in str(title or "") or "leave-one-out" in lowered or "sensitivity" in lowered:
                return "图注：敏感性分析图展示逐一剔除单项研究后的合并估计值及置信区间，用于评估主要结果是否依赖单个研究。"
            if "偏倚" in str(title or "") or "risk" in lowered or "rob" in lowered or "bias" in lowered:
                return "图注：偏倚风险图展示纳入研究的领域级判断，并用于支持证据确定性解释。"
            return "图注：该图提供相应分析的可视化摘要，应结合表格估计值和带来源链接的提取记录解释。"
        if "prisma" in lowered or "flow" in lowered:
            return (
                "Legend: The diagram summarizes record identification, duplicate removal, screening, "
                "full-text assessment, exclusions, and studies included in the qualitative and quantitative synthesis."
            )
        if "forest" in lowered:
            return (
                "Legend: The forest plot displays study-specific effect estimates and 95% CIs with the pooled "
                "estimate from the prespecified meta-analysis model. CI=confidence interval."
            )
        if "leave-one-out" in lowered or "sensitivity" in lowered:
            return (
                "Legend: The sensitivity plot shows the pooled estimate after omitting one study at a time, "
                "with confidence intervals used to assess whether the primary result depends on a single study."
            )
        if "risk" in lowered or "rob" in lowered or "bias" in lowered:
            return (
                "Legend: The risk-of-bias summary displays domain-level judgments for included studies and "
                "supports interpretation of the certainty assessment."
            )
        return (
            "Legend: The figure provides a visual summary of the corresponding analysis; the tabular estimates "
            "and source-linked extraction records provide the numeric reference."
        )

    @staticmethod
    def _backfill_publication_table_notes(manuscript: str) -> str:
        """Add concise explanatory notes below numbered tables when the draft omits them."""
        raw = str(manuscript or "")
        matches = list(re.finditer(r"^#{1,4}\s+(Table|表)\s*(\d+)\.?\s*(.*)$", raw, flags=re.I | re.M))
        if not matches:
            return manuscript
        pieces: list[str] = []
        cursor = 0
        changed = False
        for index, match in enumerate(matches):
            end = len(raw)
            if index + 1 < len(matches):
                end = matches[index + 1].start()
            section_match = WritingAgent._publication_block_boundary_match(raw[match.end():end])
            if section_match:
                end = match.end() + section_match.start()
            block = raw[match.start():end]
            pieces.append(raw[cursor:match.start()])
            if WritingAgent._table_block_has_note(block):
                pieces.append(block)
            else:
                note = WritingAgent._table_note_for_block(block, zh=match.group(1) == "表")
                separator = "\n" if block.endswith("\n") else "\n\n"
                pieces.append(block.rstrip() + separator + note + "\n")
                changed = True
            cursor = end
        pieces.append(raw[cursor:])
        return "".join(pieces) if changed else manuscript

    @staticmethod
    def _table_block_has_note(block: str) -> bool:
        return bool(
            re.search(
                r"(^|\n)\s*(?:\*\*)?(?:Note|Notes|Abbreviation|Abbreviations|Footnote|Footnotes|注|缩写)(?:\*\*)?\s*[:：.]",
                str(block or ""),
                flags=re.I,
            )
        )

    @staticmethod
    def _table_note_for_block(block: str, *, zh: bool = False) -> str:
        definitions = WritingAgent._table_abbreviation_definitions(block, zh=zh)
        if definitions:
            return ("注：" if zh else "Note: ") + "; ".join(definitions) + ("。" if zh else ".")
        return "注：数值为原始研究报告值或按预设统计方法计算值。" if zh else "Note: Values are from source reports or prespecified statistical calculations."

    @staticmethod
    def _table_abbreviation_definitions(block: str, *, zh: bool = False) -> list[str]:
        text = str(block or "")
        candidates = [
            ("OR", r"\bOR\b", "OR=优势比" if zh else "OR=odds ratio"),
            ("RR", r"\bRR\b", "RR=风险比" if zh else "RR=risk ratio"),
            ("HR", r"\bHR\b", "HR=风险比" if zh else "HR=hazard ratio"),
            ("MD", r"\bMD\b", "MD=均数差" if zh else "MD=mean difference"),
            ("SMD", r"\bSMD\b", "SMD=标准化均数差" if zh else "SMD=standardized mean difference"),
            ("CI", r"\bCI\b", "CI=置信区间" if zh else "CI=confidence interval"),
            ("SE", r"\bSE\b", "SE=标准误" if zh else "SE=standard error"),
            ("SD", r"\bSD\b", "SD=标准差" if zh else "SD=standard deviation"),
            ("GRADE", r"\bGRADE\b", "GRADE=推荐意见分级、评估、制定和评价" if zh else "GRADE=Grading of Recommendations Assessment, Development and Evaluation"),
            ("RoB", r"\bRoB\b", "RoB=偏倚风险" if zh else "RoB=risk of bias"),
            ("NR", r"\bNR\b", "NR=未报告" if zh else "NR=not reported"),
            ("I2", r"\bI\s*(?:²|\^2|2)\b", "I²=不一致性统计量" if zh else "I²=inconsistency statistic"),
        ]
        definitions: list[str] = []
        seen: set[str] = set()
        for key, pattern, definition in candidates:
            if key in seen:
                continue
            if re.search(pattern, text):
                definitions.append(definition)
                seen.add(key)
        return definitions

    @staticmethod
    def _defined_figure_numbers(manuscript: str) -> list[int]:
        numbers = []
        for match in re.finditer(r"^#{1,4}\s+(?:Figure\s+|图\s*)(\d+)\b", str(manuscript or ""), flags=re.I | re.M):
            try:
                numbers.append(int(match.group(1)))
            except ValueError:
                continue
        return sorted(set(numbers))

    @staticmethod
    def _main_text_before_figures(manuscript: str) -> str:
        raw = str(manuscript or "")
        positions = [
            match.start()
            for match in re.finditer(
                r"^#{1,6}\s+(?:Tables|Figures|Supplementary Materials|Declarations|表格|图表|参考文献|补充材料|声明)\s*[:：]?\s*$",
                raw,
                flags=re.I | re.M,
            )
        ]
        reference_match = WritingAgent._reference_heading_match(raw)
        if reference_match:
            positions.append(reference_match.start())
        return raw[:min(positions)] if positions else raw

    @staticmethod
    def _numbered_label_refs(text: str, label: str) -> list[int]:
        numbers: list[int] = []
        raw = str(text or "")
        english_raw = re.sub(
            rf"(?<=\d)\s*(,|and|[-–])\s*{re.escape(label)}s?\s*(?=\d)",
            lambda match: f" {match.group(1)} ",
            raw,
            flags=re.I,
        )
        for match in re.finditer(rf"\b{re.escape(label)}s?\s+(\d+(?:\s*(?:,|and|[-–])\s*\d+)*)", english_raw, flags=re.I):
            token = match.group(1)
            for part in re.split(r"\s*,\s*|\s+and\s+", token):
                if re.search(r"[-–]", part):
                    bounds = [item.strip() for item in re.split(r"[-–]", part, maxsplit=1)]
                    if len(bounds) != 2:
                        continue
                    try:
                        start = int(bounds[0])
                        end = int(bounds[1])
                    except ValueError:
                        continue
                    if end >= start:
                        numbers.extend(range(start, end + 1))
                else:
                    try:
                        numbers.append(int(part))
                    except ValueError:
                        continue
        chinese_label = "图" if label.lower() == "figure" else "表" if label.lower() == "table" else ""
        if chinese_label:
            chinese_raw = re.sub(
                rf"(?<=\d)\s*(,|，|、|和|及|与|至|[-–])\s*{chinese_label}\s*(?=\d)",
                lambda match: match.group(1),
                raw,
            )
            token_pattern = r"\d+(?:\s*(?:,|，|、|和|及|与|至|[-–])\s*\d+)*"
            for match in re.finditer(rf"{chinese_label}\s*({token_pattern})", chinese_raw, flags=re.I):
                token = match.group(1)
                for part in re.split(r"\s*(?:,|，|、|和|及|与)\s*", token):
                    if re.search(r"[-–]|至", part):
                        bounds = [item.strip() for item in re.split(r"[-–]|至", part, maxsplit=1)]
                        if len(bounds) != 2:
                            continue
                        try:
                            start = int(bounds[0])
                            end = int(bounds[1])
                        except ValueError:
                            continue
                        if end >= start:
                            numbers.extend(range(start, end + 1))
                    else:
                        try:
                            numbers.append(int(part))
                        except ValueError:
                            continue
        return numbers

    @staticmethod
    def _figure_reference_label(numbers: list[int]) -> str:
        ordered = sorted({number for number in numbers if number > 0})
        if not ordered:
            return "The figures"
        if len(ordered) == 1:
            return f"Figure {ordered[0]}"
        if ordered == list(range(ordered[0], ordered[-1] + 1)):
            return f"Figures {ordered[0]}-{ordered[-1]}" if len(ordered) > 2 else f"Figure {ordered[0]} and Figure {ordered[-1]}"
        return "Figures " + ", ".join(str(number) for number in ordered[:-1]) + f", and Figure {ordered[-1]}"

    @staticmethod
    def _figure_reference_label_zh(numbers: list[int]) -> str:
        ordered = sorted({number for number in numbers if number > 0})
        if not ordered:
            return "图表"
        if len(ordered) == 1:
            return f"图{ordered[0]}"
        if ordered == list(range(ordered[0], ordered[-1] + 1)):
            return f"图{ordered[0]}至图{ordered[-1]}"
        return "图" + "、图".join(str(number) for number in ordered)

    @staticmethod
    def _figure_results_summary(numbers: list[int], *, zh: bool = False) -> str:
        ordered = sorted({number for number in numbers if number > 0})
        if not ordered:
            return "未提供可用图表文件。" if zh else "No figure files were available."
        if zh:
            labels = {
                1: "研究筛选流程",
                2: "主要效应森林图",
                3: "偏倚风险概要",
                4: "逐一剔除敏感性分析",
            }
            described = [labels.get(number, f"图{number}") for number in ordered]
            return f"{WritingAgent._figure_reference_label_zh(ordered)}分别展示" + "、".join(described) + "。"
        labels = {
            1: "study-selection flow",
            2: "the primary forest plot",
            3: "the risk-of-bias summary",
            4: "leave-one-out sensitivity analysis",
        }
        described = [labels.get(number, f"Figure {number}") for number in ordered]
        if len(described) == 1:
            detail = described[0]
        else:
            detail = ", ".join(described[:-1]) + f", and {described[-1]}"
        return f"{WritingAgent._figure_reference_label(ordered)} show {detail}."

    @staticmethod
    def _append_sentence_to_section(manuscript: str, heading: str, sentence: str) -> str:
        pattern = rf"(^##\s+{re.escape(heading)}\s*$)([\s\S]*?)(?=^##\s+|\Z)"
        match = re.search(pattern, manuscript, flags=re.M)
        if not match:
            return manuscript
        body = match.group(2).rstrip()
        suffix = match.group(2)[len(body):]
        addition = ("\n\n" if body.strip() else "\n") + sentence
        return manuscript[:match.start(2)] + body + addition + suffix + manuscript[match.end(2):]

    @staticmethod
    def _is_covid_corticosteroid_topic(protocol: ResearchProtocol) -> bool:
        text = " ".join([
            getattr(protocol, "research_question", "") or "",
            getattr(protocol.pico, "population", "") or "",
            getattr(protocol.pico, "intervention", "") or "",
            getattr(protocol.pico, "outcome_primary", "") or "",
        ]).lower()
        return "covid" in text and any(
            term in text for term in ("corticosteroid", "dexamethasone", "hydrocortisone")
        )

    @staticmethod
    def _generic_event_label(effect_measure: str) -> str:
        if effect_measure in {"HR", "OR", "RR", "IRR"}:
            return "primary outcome events"
        return "events"

    @staticmethod
    def _concise_intervention_label(text: str) -> str:
        raw = re.sub(r"\s+", " ", str(text or "")).strip()
        low = raw.lower()
        if "sglt2" in low or "sodium-glucose cotransporter-2" in low:
            return "SGLT2 inhibitors"
        label = re.sub(r"\([^)]*\)", "", raw)
        label = re.split(r"\s+(?:at any|administered|as monotherapy|combined with|in combination with)\b", label, maxsplit=1, flags=re.IGNORECASE)[0]
        label = label.strip(" ,.;")
        return label or "Intervention"

    @staticmethod
    def _concise_comparator_label(text: str) -> str:
        raw = re.sub(r"\s+", " ", str(text or "")).strip()
        low = raw.lower()
        if "placebo" in low:
            return "placebo"
        if "usual care" in low and "standard" in low:
            return "usual care or standard care"
        if "usual care" in low:
            return "usual care"
        if "standard of care" in low:
            return "standard care"
        label = re.sub(r"\([^)]*\)", "", raw)
        label = re.split(
            r"\s+(?:including|with background|without an|with no|plus)\b",
            label,
            maxsplit=1,
            flags=re.IGNORECASE,
        )[0]
        label = label.strip(" ,.;")
        return label or "comparator"

    @staticmethod
    def _concise_population_label(text: str) -> str:
        raw = re.sub(r"\s+", " ", str(text or "")).strip()
        low = raw.lower()
        if "mildly reduced" in low and "preserved" in low and "ejection fraction" in low:
            return "heart failure with mildly reduced or preserved ejection fraction"
        if "hfpef" in low or "preserved ejection fraction" in low:
            return "heart failure with preserved ejection fraction"
        if "hfmref" in low or "mildly reduced ejection fraction" in low:
            return "heart failure with mildly reduced ejection fraction"
        if "covid" in low or "sars-cov-2" in low or "coronavirus" in low:
            label = re.split(r"\s+(?:including|confirmed by)\b", raw, maxsplit=1, flags=re.IGNORECASE)[0]
            return label.strip(" ,.;") or "target population"
        label = re.split(r"\s+(?:with|who|that|including)\b", raw, maxsplit=1, flags=re.IGNORECASE)[0]
        label = label.strip(" ,.;")
        return label or "target population"

    def _reporting_outcome_label(self, facts: dict, protocol: ResearchProtocol | None = None, *, zh: bool = False) -> str:
        primary = facts.get("primary_effect") if isinstance(facts.get("primary_effect"), dict) else {}
        pico = facts.get("pico") if isinstance(facts.get("pico"), dict) else {}
        protocol_outcome = protocol.pico.outcome_primary if isinstance(protocol, ResearchProtocol) else ""
        base = str(
            primary.get("outcome_name")
            or pico.get("primary_outcome")
            or protocol_outcome
            or ("主要结局" if zh else "the primary outcome")
        ).strip()
        if self._has_worsening_hf_urgent_visit_component(facts):
            return (
                "心血管死亡或心力衰竭恶化复合终点"
                if zh else
                "the composite of cardiovascular death or worsening heart failure"
            )
        return base

    @staticmethod
    def _has_worsening_hf_urgent_visit_component(facts: dict) -> bool:
        cards = facts.get("study_cards") if isinstance(facts.get("study_cards"), list) else []
        rows = (
            ((facts.get("evidence_readiness") or {}).get("selected_primary_rows") or [])
            if isinstance(facts.get("evidence_readiness"), dict) else []
        )
        texts: list[str] = []
        for item in list(cards) + list(rows):
            if not isinstance(item, dict):
                continue
            for key in (
                "primary_outcome_note",
                "llm_primary_outcome",
                "outcome_name",
                "source_quote",
                "distinctive_feature",
                "clinical_quirks",
                "audit_notes",
                "unresolved_questions",
            ):
                value = item.get(key)
                if isinstance(value, list):
                    texts.extend(str(v or "") for v in value)
                elif value not in (None, ""):
                    texts.append(str(value))
        joined = " ".join(texts).lower()
        return (
            "worsening heart failure" in joined
            and ("urgent visit" in joined or "urgent heart failure" in joined)
            and ("hospital" in joined or "hospitalization" in joined)
        )

    def _endpoint_definition_caveat(self, facts: dict, *, zh: bool = False) -> str:
        if not self._has_worsening_hf_urgent_visit_component(facts):
            return ""
        if zh:
            return (
                "需要注意的是，入池试验的复合终点定义并非完全相同：DELIVER使用“心血管死亡或心力衰竭事件”，"
                "其中心力衰竭事件包括住院或紧急就诊；EMPEROR-Preserved使用“心血管死亡或心力衰竭住院”。"
                "两项试验均包含心血管死亡，差异主要在于心力衰竭事件是否包括紧急就诊。因此，本合并估计应解释为"
                "心血管死亡或心力衰竭恶化复合终点的平均效应，而不是严格的“仅首次住院”效应；文中出现“住院”"
                "仅用于说明原始试验的来源终点定义。"
            )
        return (
            "The endpoint definition was not identical across the contributing trials: DELIVER used cardiovascular death or "
            "a worsening heart failure event, with the heart-failure component defined as hospitalization or an urgent heart "
            "failure visit, whereas EMPEROR-Preserved used cardiovascular death or heart failure hospitalization. Both trials "
            "included cardiovascular death; the difference is whether the heart-failure component included urgent visits. The "
            "pooled estimate should therefore be interpreted as the average effect on a composite of cardiovascular death or "
            "worsening heart failure, not as a hospitalization-only estimate; hospitalization wording is used only when "
            "describing the source-level trial endpoint."
        )

    def _endpoint_definition_discussion(self, facts: dict, *, zh: bool = False) -> str:
        if not self._has_worsening_hf_urgent_visit_component(facts):
            return ""
        if zh:
            return (
                "这一终点差异的临床含义是：合并估计更适合回答治疗是否减少心力衰竭恶化相关事件，"
                "而不宜被解读为仅针对住院的精确估计。若用于患者沟通或指南推荐，应结合当地急诊就诊、"
                "住院阈值和随访方式判断绝对获益。"
            )
        return (
            "Clinically, this endpoint difference means the pooled estimate is best read as an effect on worsening-heart-failure "
            "events rather than as a precise hospitalization-only effect. Translation to practice should consider local thresholds "
            "for urgent visits, hospital admission, outcome adjudication, and follow-up."
        )

    @staticmethod
    def _review_process_transparency_sentence(*, zh: bool = False) -> str:
        if zh:
            return (
                "筛选和数据提取按预设标准完成，并保留筛选、提取和核查记录供作者复核；"
                "当前项目记录未显示由两名人工评审员独立完成筛选或提取。"
            )
        return (
            "Screening and data collection followed prespecified criteria, with intermediate screening and data-collection logs retained "
            "for author verification; this manuscript does not claim independent duplicate human screening or extraction."
        )

    @staticmethod
    def _concise_outcome_label(text: str) -> str:
        raw = re.sub(r"\s+", " ", str(text or "")).strip()
        low = raw.lower()
        if "worsening heart failure" in low and "urgent" in low:
            return "the composite of cardiovascular death or worsening heart failure"
        if "all-cause mortality" in low and ("28" in low or "twenty-eight" in low):
            return "28-day all-cause mortality"
        if "mortality" in low and "covid" in low:
            return "short-term all-cause mortality"
        if "cardiovascular death" in low and "heart failure" in low and "hospital" in low:
            return "cardiovascular death or heart failure hospitalization"
        label = re.sub(r"^composite of\s+", "", raw, flags=re.IGNORECASE)
        label = label.strip(" ,.;")
        return label or "primary outcome"

    @staticmethod
    def _zh_concise_intervention_label(text: str) -> str:
        raw = re.sub(r"\s+", " ", str(text or "")).strip()
        low = raw.lower()
        if "sglt2" in low or "sodium-glucose cotransporter-2" in low:
            return "SGLT2抑制剂"
        if "corticosteroid" in low:
            return "全身性糖皮质激素"
        return raw or "干预措施"

    @staticmethod
    def _zh_concise_comparator_label(text: str) -> str:
        raw = re.sub(r"\s+", " ", str(text or "")).strip()
        low = raw.lower()
        if "placebo" in low:
            return "安慰剂"
        if "usual care" in low or "standard care" in low:
            return "常规治疗"
        return raw or "对照"

    @staticmethod
    def _zh_concise_population_label(text: str) -> str:
        raw = re.sub(r"\s+", " ", str(text or "")).strip()
        low = raw.lower()
        if (
            "hfmref" in low
            or "hfpef" in low
            or "preserved ejection fraction" in low
            or "mildly reduced ejection fraction" in low
        ):
            if "mildly reduced" in low and "preserved" in low and "ejection fraction" in low:
                return "射血分数轻度降低或保留的心力衰竭患者"
            if "hfpef" in low or "preserved ejection fraction" in low:
                return "射血分数保留的心力衰竭患者"
            return "射血分数轻度降低的心力衰竭患者"
        covid_like = "covid" in low or "sars-cov" in low or "coronavirus" in low
        critical_like = any(
            term in low
            for term in (
                "critically",
                "critical",
                "intensive care",
                "icu",
                "mechanical ventilation",
                "high-flow oxygen",
                "high flow oxygen",
                "non-invasive ventilation",
            )
        )
        if covid_like and critical_like:
            return "危重型COVID-19患者"
        if covid_like:
            return "COVID-19患者"
        return raw or "目标人群"

    @staticmethod
    def _zh_concise_outcome_label(text: str) -> str:
        raw = re.sub(r"\s+", " ", str(text or "")).strip()
        low = raw.lower()
        if "worsening heart failure" in low and "urgent" in low:
            return "心血管死亡或心力衰竭恶化复合终点"
        if "cardiovascular death" in low and "heart failure" in low and "hospital" in low:
            return "心血管死亡或心力衰竭住院"
        if ("mortality" in low or "death" in low) and ("28" in low or "28-day" in low):
            return "28天全因死亡率"
        if "mortality" in low or "death" in low:
            return "死亡"
        return raw or "主要结局"

    @staticmethod
    def _was_were_for_label(label: str) -> str:
        text = str(label or "").strip().lower()
        plural_terms = (
            " inhibitors",
            " corticosteroids",
            " interventions",
            " drugs",
            " agents",
            " therapies",
            " treatments",
        )
        return "were" if text.endswith("s") or any(term in text for term in plural_terms) else "was"

    @staticmethod
    def _has_have_for_label(label: str) -> str:
        return "have" if WritingAgent._was_were_for_label(label) == "were" else "has"

    @staticmethod
    def _sentence_initial_label(label: str) -> str:
        raw = str(label or "").strip()
        if not raw:
            return raw
        for index, char in enumerate(raw):
            if char.isalpha():
                return raw[:index] + char.upper() + raw[index + 1:]
        return raw

    def _generic_title(
        self,
        protocol: ResearchProtocol,
        intervention: str,
        outcome: str,
        *,
        report_type: str | None = None,
        facts: dict | None = None,
        allow_llm: bool = False,
    ) -> str:
        is_benchmark = str(report_type or "").strip().lower() == "benchmark_reconstruction"
        if allow_llm:
            llm_title = self._llm_generic_title(
                protocol,
                intervention,
                outcome,
                report_type=report_type,
                facts=facts or {},
            )
            if llm_title:
                return llm_title
        population = protocol.pico.population or "target population"
        if self._zh:
            short_population = self._shorten(self._zh_concise_population_label(population), 70).rstrip(".")
            short_intervention = self._shorten(self._zh_concise_intervention_label(intervention), 70).rstrip(".")
            short_outcome = self._shorten(self._zh_concise_outcome_label(outcome), 80).rstrip(".")
            suffix = "基准重建性系统综述和Meta分析" if is_benchmark else "系统综述和Meta分析"
            return f"{short_population}中{short_intervention}治疗{short_outcome}的{suffix}"
        short_population = self._shorten(self._concise_population_label(population), 70).rstrip(".")
        short_intervention = self._shorten(self._concise_intervention_label(intervention), 70).rstrip(".")
        short_outcome = self._shorten(self._concise_outcome_label(outcome), 80).rstrip(".")
        suffix = "a benchmark reconstruction and meta-analysis" if is_benchmark else "a systematic review and meta-analysis"
        return f"{short_intervention} for {short_outcome} in {short_population}: {suffix}"

    @staticmethod
    def _runtime_llm_title_enabled(project: Project | None) -> bool:
        """Use LLM title drafting in real project runs, but never from unit tests."""
        if project is None:
            return False
        return not os.environ.get("PYTEST_CURRENT_TEST")

    def _llm_generic_title(
        self,
        protocol: ResearchProtocol,
        intervention: str,
        outcome: str,
        *,
        report_type: str | None,
        facts: dict,
    ) -> str:
        prompt = self._generic_title_prompt(
            protocol,
            intervention,
            outcome,
            report_type=report_type,
            facts=facts,
        )
        try:
            candidate = self.call_llm_structured(
                prompt,
                ManuscriptTitleCandidate,
                temperature=0.0,
                max_tokens=512,
            )
        except Exception:
            return ""
        title = self._clean_title_candidate(candidate.title)
        if self._title_candidate_acceptable(title, report_type=report_type, required_outcome=outcome):
            return title
        return ""

    def _generic_title_prompt(
        self,
        protocol: ResearchProtocol,
        intervention: str,
        outcome: str,
        *,
        report_type: str | None,
        facts: dict,
    ) -> str:
        primary = facts.get("primary_effect") or {}
        prisma = facts.get("prisma") or {}
        report = str(report_type or facts.get("report_type") or "meta")
        language = "Chinese" if self._zh else "English"
        suffix_rule = (
            "The title must explicitly contain 基准重建 if the report type is benchmark_reconstruction."
            if self._zh else
            "The title must explicitly contain benchmark reconstruction if the report type is benchmark_reconstruction."
        )
        return (
            self._zh_prefix()
            + "Write one concise, publication-style title for a systematic review/meta-analysis manuscript.\n"
            + "Use only the structured facts below. Do not add claims, dates, countries, guideline statements, or effect sizes that are not listed.\n"
            + "Do not include citations, markdown, line breaks, abbreviations that are not already present, or a dangling phrase.\n"
            + "The Outcome field below is the authoritative reporting outcome for the title; do not replace it with older wording from the research question.\n"
            + f"{suffix_rule}\n"
            + f"Language: {language}\n"
            + f"Report type: {report}\n"
            + f"Research question: {protocol.research_question}\n"
            + f"Population: {protocol.pico.population}\n"
            + f"Intervention: {intervention}\n"
            + f"Comparator: {protocol.pico.comparator}\n"
            + f"Outcome: {outcome}\n"
            + f"Effect measure: {primary.get('effect_measure') or protocol.effect_measure or 'NR'}\n"
            + f"Primary studies: {primary.get('n_studies') or facts.get('primary_analysis_count') or 'NR'}\n"
            + f"Records identified: {prisma.get('records_identified') or 'NR'}\n"
            + "\nReturn JSON matching the requested schema."
        )

    @staticmethod
    def _clean_title_candidate(title: str) -> str:
        cleaned = re.sub(r"\s+", " ", str(title or "")).strip()
        cleaned = cleaned.strip(" \t\n\r\"'`#")
        cleaned = re.sub(r"\s+([:;,])", r"\1", cleaned)
        cleaned = re.sub(r"([:;,]){2,}", r"\1", cleaned)
        return cleaned.rstrip(" .")

    def _title_candidate_acceptable(self, title: str, *, report_type: str | None, required_outcome: str | None = None) -> bool:
        if not title or "\n" in title or "[" in title or "]" in title:
            return False
        if len(title) < 20 or len(title) > 220:
            return False
        lowered = title.lower()
        if any(token in lowered for token in (" p=", "95% ci", " odds ratio ", " risk ratio ", " hazard ratio ")):
            return False
        if re.search(r"\b(who are|who were|that are|that were|with|among|in|for|versus|compared with)\s*:?\s*$", lowered):
            return False
        is_benchmark = str(report_type or "").strip().lower() == "benchmark_reconstruction"
        required = str(required_outcome or "").lower()
        if "worsening heart failure" in required and "worsening" not in lowered:
            return False
        if "心力衰竭恶化" in str(required_outcome or "") and "心力衰竭恶化" not in title:
            return False
        if self._zh:
            if is_benchmark and "基准重建" not in title:
                return False
            if not is_benchmark and "基准重建" in title:
                return False
        else:
            if is_benchmark and "benchmark reconstruction" not in lowered:
                return False
            if not is_benchmark and "benchmark reconstruction" in lowered:
                return False
        return True

    def _generic_references(self, ref_manager: ReferenceManager | None) -> tuple[str, dict[str, str]]:
        entries = getattr(ref_manager, "entries", None) if ref_manager else None
        if not entries:
            return self._fallback_references(None)
        lines = []
        for idx, paper in enumerate(entries, 1):
            lines.append(self._format_reference_entry(idx, paper))
        cite_map = {str(study_id): f"[{num}]" for study_id, num in getattr(ref_manager, "_id_map", {}).items()}
        return "\n\n".join(lines), cite_map

    def _generic_study_table(self, rows: list[dict], cite_map: dict[str, str], effect_measure: str) -> str:
        lines = (
            [
                f"| 研究 | 报告位置 | 干预组事件/总数 | 对照组事件/总数 | 报告{effect_measure} | 资料依据 |",
                "|---|---|---:|---:|---:|---|",
            ]
            if self._zh
            else [
                f"| Study | Report location | Intervention events/total | Control events/total | Reported {effect_measure} | Evidence basis |",
                "|---|---|---:|---:|---:|---|",
            ]
        )
        for row in rows:
            study = self._fallback_trial_label(row)
            cite = cite_map.get(str(row.get("study_id") or ""), "")
            if cite:
                study = f"{study} {cite}"
            effect = row.get("effect")
            lines.append(
                "| "
                + " | ".join([
                    self._md_cell(study),
                    self._md_cell(self._fallback_source_location(row)),
                    f"{self._int(row.get('events_intervention'))}/{self._int(row.get('total_intervention'))}",
                    f"{self._int(row.get('events_control'))}/{self._int(row.get('total_control'))}",
                    self._fmt(effect, 2) if effect is not None else "NR",
                    (
                        "报告摘录支持" if row.get("source_quote_verified") is True else "需结合原文确认"
                    ) if self._zh else (
                        "Supported by report excerpt" if row.get("source_quote_verified") is True else "Requires report confirmation"
                    ),
                ])
                + " |"
            )
        return "\n".join(lines)

    def _generic_effect_table(self, rows: list[dict], study_stats: list[dict], effect_measure: str) -> str:
        stats_by_id = {str(item.get("study_id") or ""): item for item in study_stats if isinstance(item, dict)}
        lines = (
            [
                f"| 研究 | {effect_measure} | SE(log {effect_measure}) | 权重(%) | 来源依据 |",
                "|---|---:|---:|---:|---|",
            ]
            if self._zh
            else [
                f"| Study | {effect_measure} | SE(log {effect_measure}) | Weight (%) | Source basis |",
                "|---|---:|---:|---:|---|",
            ]
        )
        for row in rows:
            stats = stats_by_id.get(str(row.get("study_id") or ""), {})
            basis = self._generic_source_quote(row)
            lines.append(
                "| "
                + " | ".join([
                    self._md_cell(self._fallback_trial_label(row)),
                    self._fmt(stats.get("effect", row.get("effect")), 2),
                    self._fmt(stats.get("se", row.get("se")), 3),
                    self._fmt(stats.get("weight", row.get("weight")), 1),
                    self._md_cell(self._shorten(basis, 150) or ("来源支持的估计值" if self._zh else "Source-linked estimate")),
                ])
                + " |"
            )
        return "\n".join(lines)

    def _generic_absolute_effect_table(self, absolute_effects: dict | None) -> str:
        scenarios = self._absolute_effect_scenarios(absolute_effects)
        if not scenarios:
            return ""
        if self._zh:
            lines = [
                "| 基线风险来源 | 对照组风险 | 估计干预组风险 | 绝对效应 | 需治数 |",
                "|---|---:|---:|---|---|",
            ]
        else:
            lines = [
                "| Baseline risk source | Comparator risk | Estimated intervention risk | Absolute effect | NNT |",
                "|---|---:|---:|---|---|",
            ]
        for scenario in scenarios:
            if self._zh:
                row = [
                    self._md_cell(self._absolute_effect_scenario_label(scenario)),
                    self._md_cell(f"每1000人{self._int(scenario.get('assumed_control_risk_per_1000'))}例"),
                    self._md_cell(f"每1000人{self._int(scenario.get('intervention_risk_per_1000'))}例"),
                    self._md_cell(self._absolute_effect_phrase(scenario)),
                    self._md_cell(self._nnt_phrase(scenario)),
                ]
            else:
                row = [
                    self._md_cell(self._absolute_effect_scenario_label(scenario)),
                    self._md_cell(f"{self._int(scenario.get('assumed_control_risk_per_1000'))} per 1000"),
                    self._md_cell(f"{self._int(scenario.get('intervention_risk_per_1000'))} per 1000"),
                    self._md_cell(self._absolute_effect_phrase(scenario)),
                    self._md_cell(self._nnt_phrase(scenario)),
                ]
            lines.append("| " + " | ".join(row) + " |")
        return "\n".join(lines)

    def _absolute_effect_result_text(self, absolute_effects: dict | None) -> str:
        scenario = self._absolute_effect_primary_scenario(absolute_effects)
        if not scenario:
            return ""
        method_text = (
            "比例风险近似"
            if self._zh and (absolute_effects or {}).get("method") == "proportional_hazards_baseline_risk_translation"
            else "proportional hazards approximation"
            if (absolute_effects or {}).get("method") == "proportional_hazards_baseline_risk_translation"
            else "基线风险换算"
            if self._zh
            else "baseline-risk translation"
        )
        if self._zh:
            scenario_note = "表4显示该换算场景。"
            if len(self._absolute_effect_scenarios(absolute_effects)) > 1:
                scenario_note = "表4同时显示不同基线风险人群下的换算场景。"
            return (
                "### 绝对效应换算\n"
                f"以本综述纳入试验对照组在试验随访期内观察到的平均累积事件风险（每1000人{self._int(scenario.get('assumed_control_risk_per_1000'))}例）为基线，"
                f"按{method_text}应用合并效应后，干预组估计风险为每1000人{self._int(scenario.get('intervention_risk_per_1000'))}例，"
                f"即{self._absolute_effect_phrase(scenario)}；{self._nnt_phrase(scenario)}。这是基于本综述观察到的随访期累积基线风险和合并效应的临床换算，"
                f"隐含效应量可近似应用于试验随访期内累积风险的假设；实际绝对获益会随随访时间、当地事件判定和患者基线风险而变化。"
                f"该数值不是可直接外推到所有人群的绝对风险差。{scenario_note}"
            )
        scenario_note = "Table 4 shows this scenario."
        if len(self._absolute_effect_scenarios(absolute_effects)) > 1:
            scenario_note = "Table 4 also shows lower- and higher-baseline-risk scenarios."
        return (
            "### Absolute-effect translation\n"
            f"Using the average observed cumulative comparator event risk over trial follow-up in the included trials ({self._int(scenario.get('assumed_control_risk_per_1000'))} per 1000), "
            f"applying the pooled effect with a {method_text} gives an estimated intervention risk of "
            f"{self._int(scenario.get('intervention_risk_per_1000'))} per 1000, or "
            f"{self._absolute_effect_phrase(scenario)}; approximate {self._nnt_phrase(scenario)}. This clinical translation uses the observed cumulative baseline risk over trial follow-up "
            "and assumes the pooled relative effect can approximate cumulative risk over the trial follow-up; the absolute benefit may vary with "
            f"follow-up duration, local event definitions, and patient baseline risk. It is not a universal absolute risk difference. {scenario_note}"
        )

    def _absolute_effect_discussion_text(self, absolute_effects: dict | None) -> str:
        scenario = self._absolute_effect_primary_scenario(absolute_effects)
        if not scenario:
            return ""
        if self._zh:
            return (
                "结果部分和表4已经给出基于观察到的对照组风险以及不同基线风险场景的绝对效应换算。"
                "讨论中更重要的是如何使用这些换算：相同相对效应在高风险人群中会产生更大的绝对获益，"
                "在低风险人群中则可能转化为较小的短期绝对获益。"
            )
        return (
            "The Results section and Table 4 provide the numerical absolute-effect translation using the observed "
            "comparator risk and alternative baseline-risk scenarios. In clinical use, the key point is that the same "
            "relative effect produces larger absolute benefit in higher-risk patients and smaller short-term absolute "
            "benefit in lower-risk patients."
        )

    def _intervention_scope_sentence(self, facts: dict | None) -> str:
        examples = self._primary_intervention_examples(facts)
        if not examples:
            return ""
        if self._zh:
            localized = [self._zh_drug_name(item) for item in examples]
            joined = "、".join(localized)
            return f"该估计主要反映入池试验中{joined}的平均效应，外推至其它同类干预时仍需结合相应证据。"
        if len(examples) == 1:
            joined = examples[0]
        else:
            joined = ", ".join(examples[:-1]) + f", and {examples[-1]}"
        return (
            f"The direct estimate primarily reflects the contributing {joined} trial evidence; "
            "application to other SGLT2 inhibitors is a class-mechanism inference rather than direct trial evidence from this synthesis. "
        )

    def _primary_study_names_sentence(self, facts: dict | None) -> str:
        names = self._primary_study_names(facts)
        if not names:
            return ""
        if self._zh:
            joined = "、".join(names)
            return f"入池研究为{joined}；"
        if len(names) == 1:
            joined = names[0]
        else:
            joined = ", ".join(names[:-1]) + f", and {names[-1]}"
        return f"The contributing studies were {joined}. "

    def _primary_study_intervention_sentence(self, facts: dict | None) -> str:
        mapping = self._primary_study_intervention_map(facts)
        if not mapping:
            return ""
        if self._zh:
            parts = [f"{study}（{self._zh_drug_name(drug)}）" for study, drug in mapping]
            if len(parts) == 1:
                joined = parts[0]
            else:
                joined = "、".join(parts[:-1]) + f"和{parts[-1]}"
            return f"入池研究为{joined}；"
        parts = [f"{study} ({drug})" for study, drug in mapping]
        if len(parts) == 1:
            joined = parts[0]
        else:
            joined = ", ".join(parts[:-1]) + f", and {parts[-1]}"
        return f"The contributing trial rows were {joined}. "

    @staticmethod
    def _primary_study_intervention_map(facts: dict | None) -> list[tuple[str, str]]:
        facts = facts if isinstance(facts, dict) else {}
        cards = facts.get("study_cards") if isinstance(facts.get("study_cards"), list) else []
        known_order = [
            "empagliflozin",
            "dapagliflozin",
            "sotagliflozin",
            "canagliflozin",
            "dexamethasone",
            "hydrocortisone",
            "methylprednisolone",
        ]
        mapping: list[tuple[str, str]] = []
        for card in cards:
            if not isinstance(card, dict):
                continue
            study = str(card.get("display_name") or card.get("study_label") or "").strip()
            if not study:
                continue
            blob = " ".join([
                str(card.get("intervention") or ""),
                str(card.get("source_quote") or ""),
            ]).lower()
            drug = next((name for name in known_order if re.search(rf"\b{re.escape(name)}\b", blob)), "")
            if not drug:
                continue
            pair = (study, drug)
            if pair not in mapping:
                mapping.append(pair)
        return mapping[:4]

    @staticmethod
    def _primary_study_names(facts: dict | None) -> list[str]:
        facts = facts if isinstance(facts, dict) else {}
        names: list[str] = []
        for card in facts.get("study_cards") or []:
            if not isinstance(card, dict):
                continue
            name = str(card.get("display_name") or card.get("study_label") or "").strip()
            if name and name not in names:
                names.append(name)
        return names[:4]

    def _primary_intervention_examples_sentence(self, facts: dict | None) -> str:
        examples = self._primary_intervention_examples(facts)
        if not examples:
            return ""
        if self._zh:
            localized = [self._zh_drug_name(item) for item in examples]
            return "入池试验评估的具体药物包括" + "、".join(localized) + "；"
        if len(examples) == 1:
            joined = examples[0]
        else:
            joined = ", ".join(examples[:-1]) + f", and {examples[-1]}"
        return f"The contributing trials evaluated {joined}. "

    @staticmethod
    def _primary_intervention_examples(facts: dict | None) -> list[str]:
        facts = facts if isinstance(facts, dict) else {}
        cards = facts.get("study_cards") if isinstance(facts.get("study_cards"), list) else []
        rows = ((facts.get("evidence_readiness") or {}).get("selected_primary_rows") or []) if isinstance(facts.get("evidence_readiness"), dict) else []
        texts: list[str] = []
        for item in list(cards) + list(rows):
            if not isinstance(item, dict):
                continue
            texts.extend([
                str(item.get("intervention") or ""),
                str(item.get("source_quote") or ""),
            ])
        blob = " ".join(texts).lower()
        known_order = [
            "empagliflozin",
            "dapagliflozin",
            "sotagliflozin",
            "canagliflozin",
            "dexamethasone",
            "hydrocortisone",
            "methylprednisolone",
        ]
        found = [name for name in known_order if re.search(rf"\b{re.escape(name)}\b", blob)]
        if found:
            return found[:4]
        inferred: list[str] = []
        for match in re.finditer(r"\b(?:in the|the)\s+([A-Za-z][A-Za-z0-9 -]{2,40}?)\s+group\b", blob):
            name = re.sub(r"\s+", " ", match.group(1)).strip(" -")
            if not name or name in {"placebo", "control", "usual care", "standard care", "intervention"}:
                continue
            if len(name.split()) > 4:
                continue
            if name not in inferred:
                inferred.append(name)
        return inferred[:4]

    @staticmethod
    def _zh_drug_name(name: str) -> str:
        mapping = {
            "empagliflozin": "恩格列净",
            "dapagliflozin": "达格列净",
            "sotagliflozin": "索格列净",
            "canagliflozin": "卡格列净",
            "dexamethasone": "地塞米松",
            "hydrocortisone": "氢化可的松",
            "methylprednisolone": "甲泼尼龙",
        }
        return mapping.get(str(name or "").strip().lower(), str(name or "").strip())

    @staticmethod
    def _absolute_effect_scenarios(absolute_effects: dict | None) -> list[dict]:
        scenarios = (absolute_effects or {}).get("scenarios") if isinstance(absolute_effects, dict) else None
        if not isinstance(scenarios, list):
            return []
        return [scenario for scenario in scenarios if isinstance(scenario, dict)]

    @staticmethod
    def _absolute_effect_primary_scenario(absolute_effects: dict | None) -> dict:
        scenarios = WritingAgent._absolute_effect_scenarios(absolute_effects)
        if not scenarios:
            return {}
        return scenarios[0]

    def _absolute_effect_scenario_label(self, scenario: dict) -> str:
        if self._zh:
            return str(scenario.get("label_zh") or scenario.get("label") or "基线风险场景")
        return str(scenario.get("label") or "Baseline-risk scenario")

    def _absolute_effect_range_text(self, absolute_effects: dict | None) -> str:
        scenarios = self._absolute_effect_scenarios(absolute_effects)
        values = sorted({
            self._int(scenario.get("events_avoided_per_1000"))
            for scenario in scenarios
            if self._int(scenario.get("events_avoided_per_1000")) > 0
        })
        if len(values) < 2:
            return ""
        low, high = values[0], values[-1]
        if self._zh:
            return f"为每1000人减少{low}至{high}例事件"
        return f"range from {low} to {high} fewer events per 1000"

    def _absolute_effect_phrase(self, scenario: dict) -> str:
        avoided = self._int(scenario.get("events_avoided_per_1000"))
        increased = self._int(scenario.get("events_increased_per_1000"))
        if scenario.get("absolute_ci_crosses_null") is True:
            fewer = self._int(scenario.get("events_avoided_ci_high_per_1000"))
            more = self._int(scenario.get("events_increased_ci_high_per_1000"))
            if self._zh:
                return f"每1000人减少{avoided}例事件（95% CI 从减少{fewer}例至增加{more}例）"
            return f"{avoided} fewer events per 1000 (95% CI {fewer} fewer to {more} more)"
        if avoided:
            low = self._int(scenario.get("events_avoided_ci_low_per_1000"))
            high = self._int(scenario.get("events_avoided_ci_high_per_1000"))
            if self._zh:
                ci = f"（95% CI 减少{low}至{high}例）" if low and high else ""
                return f"每1000人减少{avoided}例事件{ci}"
            ci = f" (95% CI {low} to {high} fewer)" if low and high else ""
            return f"{avoided} fewer events per 1000{ci}"
        if increased:
            low = self._int(scenario.get("events_increased_ci_low_per_1000"))
            high = self._int(scenario.get("events_increased_ci_high_per_1000"))
            if self._zh:
                ci = f"（95% CI 增加{low}至{high}例）" if low and high else ""
                return f"每1000人增加{increased}例事件{ci}"
            ci = f" (95% CI {low} to {high} more)" if low and high else ""
            return f"{increased} more events per 1000{ci}"
        return "每1000人绝对差异接近0例" if self._zh else "an absolute difference near 0 events per 1000"

    def _nnt_phrase(self, scenario: dict) -> str:
        nnt = self._int(scenario.get("nnt"))
        if not nnt:
            return "需治数未估计" if self._zh else "NNT not estimable"
        nnt_type = str(scenario.get("nnt_type") or "").upper()
        if not nnt_type:
            nnt_type = "NNTB" if self._int(scenario.get("events_avoided_per_1000")) else "NNH" if self._int(scenario.get("events_increased_per_1000")) else "NNT"
        low = self._int(scenario.get("nnt_ci_low"))
        high = self._int(scenario.get("nnt_ci_high"))
        crosses_null = scenario.get("absolute_ci_crosses_null") is True
        if self._zh:
            label = "获益需治数" if nnt_type == "NNTB" else "伤害需治数" if nnt_type == "NNH" else "需治数"
            if crosses_null:
                return f"{label}{nnt}（95% CI跨越无效值，因此区间需治数不有限）"
            ci = f"（95% CI {low}至{high}）" if low and high else ""
            return f"{label}{nnt}{ci}"
        if crosses_null:
            return f"{nnt_type} {nnt} (the 95% CI crosses no effect, so a finite NNT interval is not defined)"
        ci = f" (95% CI {low} to {high})" if low and high else ""
        return f"{nnt_type} {nnt}{ci}"

    def _generic_source_audit_table(self, rows: list[dict]) -> str:
        lines = (
            [
                "| 研究 | 行ID | 来源位置 | 来源依据 | 提取置信度 |",
                "|---|---|---|---|---|",
            ]
            if self._zh
            else [
                "| Study | Row ID | Source location | Source basis | Confidence |",
                "|---|---|---|---|---|",
            ]
        )
        for row in rows:
            lines.append(
                "| "
                + " | ".join([
                    self._md_cell(self._fallback_trial_label(row)),
                    self._md_cell(self._fallback_row_id(row)),
                    self._md_cell(self._fallback_source_location(row)),
                    self._md_cell(self._shorten(self._generic_source_quote(row), 180) or "NR"),
                    self._md_cell(row.get("extraction_confidence") or "NR"),
                ])
                + " |"
            )
        return "\n".join(lines)

    def _generic_source_quote(self, row: dict) -> str:
        effect = row.get("effect")
        if effect is not None:
            counts = (
                f"{self._int(row.get('events_intervention'))}/{self._int(row.get('total_intervention'))} vs "
                f"{self._int(row.get('events_control'))}/{self._int(row.get('total_control'))}"
            )
            if self._zh:
                return f"{counts}；报告效应量 {self._fmt(effect, 2)}。"
            return f"{counts}; reported effect {self._fmt(effect, 2)}."
        text = str(row.get("source_quote") or "")
        return re.sub(r"\bpatients\b", "participants", text, flags=re.IGNORECASE)

    @staticmethod
    def _fallback_search_date(search: dict | None) -> str:
        search = search or {}
        for key in ("search_date", "date", "run_date", "retrieved_at", "created_at"):
            raw = str(search.get(key) or "").strip()
            if raw:
                return raw[:10]
        return date.today().isoformat()

    def _fallback_prisma_flow_legend(
        self,
        *,
        prisma: dict | None,
        n_primary: int | None = None,
    ) -> str:
        prisma = prisma or {}
        records = self._int(prisma.get("records_identified"))
        duplicates = self._int(prisma.get("duplicates_removed"))
        dedup = self._int(prisma.get("records_after_dedup"))
        screened = self._int(prisma.get("title_abstract_screened")) or dedup
        full_text = self._int(prisma.get("full_text_assessed"))
        included = self._int(prisma.get("studies_included"))
        quantitative = self._int(n_primary) or self._int(prisma.get("studies_quantitative")) or included
        if self._zh:
            return (
                f"图注：PRISMA流程图显示共识别{records}条记录，删除{duplicates}条重复记录后"
                f"{dedup}条进入去重后记录集；筛选{screened}条题名/摘要记录，全文评估{full_text}篇，"
                f"最终纳入{included}项研究，其中{quantitative}项进入定量合成。"
            )
        return (
            f"Legend: The PRISMA flow diagram shows {records} records identified, {duplicates} duplicates removed, "
            f"{dedup} records after deduplication, {screened} records screened, {full_text} full-text reports assessed, "
            f"{included} studies included, and {quantitative} studies in the quantitative synthesis."
        )

